'use strict';
const M=TattooModel, B=BookingTools, KEY='tattoo-marketplace-prototype-v1';
const names={requested:'Enquiry sent',quoted:'Quote ready',confirmed:'Booked',started:'In session',completed:'Completed',reviewed:'Reviewed',cancelled:'Cancelled'};
const artFiles=['assets/lotus.webp','assets/snake.webp','assets/colour-snake.webp'];
const seed=()=>({
  client:{name:'Demo client',signedIn:false,email:'',phone:''},
  profile:{name:'Demo artist',studio:'Independent tattoo artist',about:'Custom tattoos, thoughtful placement and an individual consultation for every idea.',area:'HSR Layout',city:'Bangalore',styles:['Fine line','Black & grey'],starting:3000,approved:true,active:true,submitted:false},
  home:{enabled:true,areas:'HSR Layout, Singasandra, Electronic City',radius:12,travel:500,note:'The appointment and setup requirements are agreed during consultation.'},
  wallet:{balance:500,transactions:[{label:'Opening demo balance',amount:500}]},feePolicy:'fixed-100-v1',setup:{details:true,portfolio:true,appointments:true},saved:[],
  bookings:[{id:'T-1001',artist:0,client:'Demo client',idea:'A custom snake with flowing leaves. Clean negative space and a strong silhouette.',placement:'Outer forearm',size:'About 6 inches',budget:'₹10,000–₹15,000',service:'studio',area:'HSR Layout',address:'',datePreference:'Flexible',status:'requested',createdAt:Date.now(),shareToken:B.id('link'),source:'marketplace',quote:null,charged:false,messages:[{from:'client',text:'Hi! I would like a custom snake tattoo on my outer forearm. Can we discuss the design?'}],reference:'Sample snake design',referenceImage:'assets/snake.webp'}],
  tickets:[],gallery:[...artFiles],selectedBooking:'T-1001',selectedArtist:0,search:{city:'Bangalore',service:'either',style:'All styles',maxPrice:100000,name:''},draft:{idea:'',placement:'',size:'',budget:'Not sure yet',service:'studio',area:'',datePreference:'Flexible',reference:''}
});
let S,lastObservedStorage='';
try{lastObservedStorage=localStorage.getItem(KEY)||'';S=JSON.parse(lastObservedStorage)||seed();if(!S.profile||!Array.isArray(S.bookings))S=seed();}catch{S=seed();}
M.migrateDemoFees(S);B.ensure(S);
S.setup=S.setup||{details:!!S.profile.approved,portfolio:!!S.profile.approved,appointments:!!S.profile.approved};
// Upgrade existing browser drafts and filters without clearing their bookings or wallet.
S.search={city:'Bangalore',service:'either',style:'All styles',...S.search,
 maxPrice:priceLimit(S.search.maxPrice??(S.search.budget==='Under ₹5,000'?5000:S.search.budget==='Under ₹10,000'?10000:100000)),name:S.search.name||''};
delete S.search.budget;delete S.search.area;
let enquiryStep=1, rating=0, referenceURL='', localGallery=[], bodyView='front';
let authPreview={step:'phone',phone:'',expires:0,attempts:0};
const chatDrafts=new Map(),reviewDrafts=new Map();
function priceLimit(value){const n=Number(value);return Number.isFinite(n)?Math.min(100000,Math.max(0,Math.round(n/500)*500)):100000;}
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const save=()=>{try{const value=JSON.stringify(S);localStorage.setItem(KEY,value);lastObservedStorage=value;if(typeof CloudStore!=='undefined')CloudStore.queue(S);return true;}catch{toast('Browser storage is unavailable; this preview will reset when reloaded.');return false;}};
const route=()=>location.hash.slice(1).split('?')[0]||'home';
const inProfileSetup=()=>!!location.hash.split('?')[1]?.split('&').includes('setup=1');
const setupBack=()=>a('artist-onboarding','← Back to profile setup','back');
const go=(r)=>{location.hash=r;};
const a=(route,text,classes='btn')=>`<a href="#${route}" class="${classes}">${text}</a>`;
const bookingLink=(r,b,text,classes='btn')=>`<a href="#${r}?booking=${encodeURIComponent(b.id)}" data-booking="${e(b.id)}" class="${classes}">${text}</a>`;
function bookingFromRoute(){const match=location.hash.match(/[?&]booking=([^&]+)/);if(!match)return null;try{const id=decodeURIComponent(match[1]);return S.bookings.some(b=>b.id===id)?id:null;}catch{return null;}}
const btn=(action,text,classes='btn',extra='')=>`<button type="button" data-action="${action}" class="${classes}" ${extra}>${text}</button>`;
const tag=(text,type='')=>`<span class="badge ${type}">${e(text)}</span>`;
const formField=(label,name,value='',type='text',hint='',required=false)=>`<div class="field"><label class="label" for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''}>${hint?`<div class="help">${hint}</div>`:''}</div>`;
const selectField=(label,name,values,current)=>`<div class="field"><label class="label" for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${values.map(v=>`<option ${v===current?'selected':''}>${e(v)}</option>`).join('')}</select></div>`;
const textField=(label,name,value='',hint='',required=false)=>`<div class="field"><label class="label" for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${e(value)}</textarea>${hint?`<div class="help">${hint}</div>`:''}</div>`;
const row=(label,value)=>`<div class="detail-row"><span>${label}</span><strong>${value}</strong></div>`;
const head=(label,title,description='',actions='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1 style="margin-top:10px">${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const currentBooking=()=>S.bookings.find(b=>b.id===S.selectedBooking)||S.bookings[0];
const artists=()=>[
 {id:0,name:S.profile.name,area:S.profile.area,city:S.profile.city,styles:S.profile.styles,starting:S.profile.starting,home:S.home.enabled,image:S.gallery[0],label:'Independent artist',about:S.profile.about},
 {id:1,name:'Black & Grey Studio',area:'Indiranagar',city:'Bangalore',styles:['Black & grey','Realism'],starting:6000,home:false,image:artFiles[1],label:'Sample studio',about:'A sample profile focused on black-and-grey work and custom compositions.'},
 {id:2,name:'Colour & Form',area:'Electronic City',city:'Bangalore',styles:['Colour','Illustrative'],starting:4500,home:true,image:artFiles[2],label:'Sample artist',about:'A sample profile for colourful, illustrative tattoos and custom concepts.'}
];
const selectedArtist=()=>artists().find(x=>x.id===S.selectedArtist)||artists()[0];
const artistFor=b=>artists().find(x=>x.id===b.artist)||artists()[0];
const homeConfig=x=>x.id===0?S.home:{enabled:x.home,areas:'Electronic City, Singasandra',radius:8,travel:700,note:'Home visits available by arrangement.'};
const visibleArtists=()=>artists().filter(x=>x.id!==0||M.visible(S.profile,S.wallet));
function matches(x){
 const z=S.search;
 if(x.city.toLowerCase()!==z.city.trim().toLowerCase())return false;
 if(z.service==='home'&&!x.home)return false;
 if(z.style!=='All styles'&&!x.styles.includes(z.style))return false;
 if(x.starting>priceLimit(z.maxPrice))return false;
 if(z.name&&!x.name.toLowerCase().includes(z.name.trim().toLowerCase()))return false;
 return true;
}
const screens=[
 ['home','Client','Welcome & search','Location and appointment preference'],['artists','Client','Artist results','Portfolio-first cards and filters'],['profile','Client','Artist profile','Work, styles, prices and home service'],['enquiry','Client','Tattoo enquiry','Three short steps, with a saved draft'],['login','Client','Sign in','Google or phone/OTP sign-in preview'],['requests','Client','My requests','Enquiries, quotes and booking updates'],['conversation','Client','Consultation','Brief, messages and image attachments'],['quote','Client','Review quote','Tattoo amount, travel, date and address'],['advance','Client','Pay booking advance','Successful advance payment confirms the appointment'],['appointment','Client','Appointment details','Status, price and start-session code'],['appointments','Client','My appointments','Upcoming and past sessions'],['review','Client','Leave a review','Available after the session is completed'],['saved','Client','Saved artists','Shortlist and revisit profiles'],['account','Client','Account','Name, contact details and preferences'],['help','Client','Help & support','Booking-specific support requests'],
 ['artist-welcome','Artist','Join the platform','Showcase your work and find clients'],['artist-signup','Artist','Create account','Simple contact details'],['artist-onboarding','Artist','Set up profile','Portfolio, services and review submission'],['artist-dashboard','Artist','Overview','Current enquiries, appointments and wallet'],['artist-enquiries','Artist','Enquiries','Client briefs and enquiry status'],['artist-enquiry','Artist','Consultation','Read the brief, share images, reply or decline'],['artist-quote','Artist','Create quote','Amount, location, date and time'],['artist-bookings','Artist','Bookings','Confirmed and completed appointments'],['artist-booking','Artist','Booking details','Accepted quote and session actions'],['artist-start','Artist','Start session','OTP validation and commission deduction'],['artist-complete','Artist','Finish session','Completion and aftercare message'],['artist-wallet','Artist','Wallet','Balance, fee history and visibility status'],['artist-portfolio','Artist','Portfolio','Artwork and Instagram portfolio links'],['artist-home','Artist','Home service','Availability, areas and travel charge'],['artist-settings','Artist','Profile & settings','Profile details and public availability'],
 ['admin-dashboard','Admin','Operations overview','Approvals, booking issues and support'],['admin-artists','Admin','Artist approval','Review the submitted sample profile'],['admin-bookings','Admin','Booking oversight','View prices, statuses and commission'],['admin-support','Admin','Support queue','Handle demo reports and closures'],['workflow','Design','Workflow & rules','Client, artist and admin journeys'],['screens','Design','All screens','A navigable page directory']
];
function topbar(r){let role=r.startsWith('artist-')?'artist':r.startsWith('admin-')?'admin':['workflow','screens'].includes(r)?'design':'client';return `<div class="prototype"><div class="context"><strong>Design preview</strong><span>Sample profiles · No live messages or payments</span></div><nav class="preview-nav" aria-label="Prototype navigation">${[['home','Client','client'],['artist-dashboard','Artist','artist'],['admin-dashboard','Admin','admin'],['workflow','Workflow','design'],['screens','All screens','design']].map(([url,t,k])=>a(url,t,role===k&&(k!=='design'||r===url)?'active':'')).join('')}${btn('reset','Reset demo','','aria-label="Reset all demo data"')}</nav><span id="workspace-sync-status" class="sync-status">Private preview</span></div>`;}
function header(r){const ar=r.startsWith('artist-'),ad=r.startsWith('admin-');return `<header class="header">${a('home','<span class="brand-logo-symbol" aria-hidden="true"><img class="brand-logo-image" src="assets/makemytattoo-diagonal-pin-v6.png" alt=""></span><span class="brand-wordmark"><span>MakeMyTattoo</span><small>by sorrymom.</small></span>','brand')}<nav aria-label="Main navigation">${ar?`${a('artist-dashboard','Inbox',r==='artist-dashboard'?'active':'')}${a('artist-calendar','Calendar',r==='artist-calendar'?'active':'')}${a('artist-payments','Payments',r==='artist-payments'?'active':'')}${a('home','Marketplace','')}`:ad?`${a('admin-dashboard','Operations','')}${a('admin-metrics','Pilot insights','')}${a('home','Marketplace','')}`:`${a('artists','Find artists',['home','artists','profile','artist'].includes(r)?'active':'')}${a('requests','My tattoos',['requests','booking','conversation','quote','advance','appointment','appointments','review'].includes(r)?'active':'')}${a('saved','Saved',r==='saved'?'active':'')}${a(S.client.signedIn?'account':'login',S.client.signedIn?'Account':'Sign in','')}${a('artist-welcome','For artists','')}`}</nav></header>`;}

function sidebar(r,admin=false){const entries=admin?[['admin-dashboard','Overview'],['admin-artists','Artist approval'],['admin-bookings','Bookings'],['admin-metrics','Pilot insights'],['admin-support','Support']]:[['artist-dashboard','Inbox'],['artist-calendar','Calendar'],['artist-payments','Payments'],['artist-links','Booking links'],['artist-portfolio','Portfolio'],['artist-settings','Profile & settings']];return `<aside class="sidebar"><div class="side-label eyebrow">${admin?'Operations':'Artist workspace'}</div><nav aria-label="${admin?'Admin':'Artist'} navigation">${entries.map(([url,t])=>a(url,t,r===url?'active':'')).join('')}</nav>${!admin?`<div class="sidebar-tools">${a('artist-templates','Quote templates & replies','small')}${a('artist-home','Home-service settings','small')}${a('artist-bookings','All booked sessions','small')}</div><div class="note">${M.visible(S.profile,S.wallet)?'● Your profile is visible':'○ Your profile is paused'}<br><br>${S.wallet.balance<0?'Clear your wallet dues to restore visibility.':!S.profile.approved?'Your profile needs approval before it appears in search.':'Manage availability in your calendar.'}</div>`:''}</aside>`;}

function footer(){return `<footer class="footer"><span>MakeMyTattoo · by sorrymom.</span><div class="actions">${a('help','Help','')}${a('workflow','Workflow & design rules','')}${a('screens','Page directory','')}</div></footer>`;}
function artistCard(x){const saved=S.saved.includes(x.id);return `<article class="card artist-card"><a href="#profile" data-artist="${x.id}" aria-label="View ${e(x.name)}"><img class="art" src="${e(x.image)}" alt="Sample ${e(x.styles.join(' and '))} tattoo artwork"></a><div class="info"><div class="actions">${tag(x.label)}${x.home?tag('Home service','green'):''}</div><h3>${a('profile',e(x.name),'')}</h3><p class="small">${e(x.area)} · ${e(x.styles.join(' / '))}</p>${matchReasons(x)}${BookingTools.reviewStats(S,x.id).count?`<p class="small">★ ${BookingTools.reviewStats(S,x.id).rating} · ${BookingTools.reviewStats(S,x.id).count} booking-linked reviews</p>`:''}<div class="card-meta"><span>From <strong>${money(x.starting)}</strong></span>${btn('save-artist',saved?'♥':'♡','save',`data-id="${x.id}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} ${e(x.name)}"`)}</div><div style="margin-top:14px">${a('profile','View work →','btn full compact')}</div><div class="display-only">Sample profile · illustrative starting price</div></div></article>`;}
function homeSearch(){return `<form class="card home-search" data-form="search"><h2>Find your tattoo artist</h2><p class="small" style="margin-top:8px">Browse first. Sign in when you’re ready to contact an artist.</p><div class="field" style="margin-top:22px"><label class="label" for="home-city">Your city</label><input id="home-city" name="city" value="${e(S.search.city)}" autocomplete="address-level2" required></div><div class="label">Where would you like your tattoo?</div><div class="chips" role="group" aria-label="Appointment location">${[['either','Either'],['studio','At a studio'],['home','At my place']].map(([v,t])=>btn('service',t,'chip',`data-value="${v}" aria-pressed="${S.search.service===v}"`)).join('')}</div><button class="btn primary full" style="margin-top:24px" type="submit">Find tattoo artists →</button></form>`;}
function signInCard(){return `<section class="card signin-card" aria-labelledby="signin-title"><span class="eyebrow">Your tattoo starts here</span><h2 id="signin-title">Find your artist.<br>Make it personal.</h2><p class="small signin-intro">Sign in to save artists, chat and book.</p>${btn('google-preview','<span class="google-letter" aria-hidden="true">G</span> Continue with Google','btn full google-signin')}<div class="signin-divider"><span>or use your mobile number</span></div>${authPreview.step==='otp'?`<form data-form="verify-login"><p class="small">Code for ${e(authPreview.phone)}</p><div class="field" style="margin-top:16px"><label class="label" for="signin-code">Enter 6-digit code</label><input id="signin-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></div><p class="demo-auth-note">Preview code: <strong>123456</strong>. No SMS was sent.</p><div class="error" data-error role="alert" hidden></div><button class="btn primary full" type="submit">Verify & continue</button><div class="actions auth-secondary">${btn('resend-demo-code','Resend demo code','btn ghost')}${btn('change-login-number','Change number','btn ghost')}</div></form>`:`<form data-form="phone-login"><div class="field"><label class="label" for="signin-phone">Mobile number</label><input id="signin-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+91 99999 99999" value="${e(authPreview.phone)}" required></div><div class="error" data-error role="alert" hidden></div><button class="btn primary full" type="submit">Get OTP</button></form>`}<p class="demo-auth-note">Design preview · Google and SMS sign-in are simulated. Use demo details.</p>${a('artists','<strong>Find tattoo artists →</strong><small>Browse first</small>','btn full browse-artists-cta')}</section>`;}
function homePage(){return `<main class="content home welcome-home"><div class="welcome-copy"><h1 class="hero-title">Great tattoos start<br><em>with the right artist.</em></h1><p class="lead">Your idea. An artist who gets it.<br>A booking made simple.</p><ol class="welcome-steps"><li><span>01</span><div><strong>Find your artist</strong></div></li><li><span>02</span><div><strong>Share your idea</strong></div></li><li><span>03</span><div><strong>Book your session</strong></div></li></ol><div class="welcome-values"><span>Your style</span><span>Clear prices</span><span>Studio or home</span></div></div><div class="welcome-entry">${homeSearch()}${!S.client.signedIn?`<details class="welcome-signin"><summary>Already planning your tattoo? Sign in</summary>${signInCard()}</details>`:''}</div></main>`;}
function artistsPage(){
 const list=visibleArtists().filter(matches);
 return `<main class="content">${head('Find your fit','Explore tattoo artists',`Artists in ${e(S.search.city)} · ${S.search.service==='home'?'Home service':S.search.service==='studio'?'Studio appointments':'Studio & home-service options'}`)}
 <form data-form="filters" class="filters">
 <div class="field artist-name-search"><label class="label" for="artist-name-search">Looking for someone specific?</label><input id="artist-name-search" name="artistName" type="search" value="${e(S.search.name)}" placeholder="Search artist or studio name" aria-label="Search artist or studio name"></div>
 ${formField('City','city',S.search.city)}
 ${selectField('Style','style',['All styles','Fine line','Black & grey','Realism','Colour','Illustrative'],S.search.style)}
 <div class="field price-filter"><div class="price-heading"><label class="label" for="starting-price">Starting price up to</label><output id="starting-price-value" for="starting-price" aria-live="polite">${money(S.search.maxPrice)}</output></div><div class="price-control"><input class="price-slider" id="starting-price" name="maxPrice" type="range" min="0" max="100000" step="500" value="${S.search.maxPrice}" aria-valuetext="${money(S.search.maxPrice)}" aria-describedby="price-range-help"></div></div>
 ${selectField('Appointment','service',['Either','At a studio','At my place'],S.search.service==='home'?'At my place':S.search.service==='studio'?'At a studio':'Either')}
 <div class="filter-footer"><p class="help" id="price-range-help">Filter artist starting prices from ₹0 to ₹1,00,000. Your tattoo’s final quote depends on its design, size and placement.</p><div class="actions">${btn('clear-filters','Reset','btn')}<button class="btn primary" type="submit">Apply filters</button></div></div></form>
 <div class="summary-row"><span>${list.length} ${list.length===1?'artist':'artists'} found${S.search.name?' for “'+e(S.search.name)+'”':''}</span><span class="small">Match by name, style and budget</span></div>
 ${list.length?`<div class="grid">${list.map(artistCard).join('')}</div>`:`<div class="card empty"><h2>No matching artists yet.</h2><p>Try another artist name, a wider budget or a different style or appointment preference.</p>${btn('clear-filters','Clear filters','btn primary')}${a('home','Change city','btn')}</div>`}
 <p class="display-only" style="margin-top:22px">All profiles and prices in this prototype are examples. Artwork is used as design reference, not as proof of an artist’s completed work.</p></main>`;
}
function profilePage(){const x=selectedArtist(),hc=homeConfig(x);if(x.id===0&&!M.visible(S.profile,S.wallet))return `<main class="content tiny"><div class="card empty"><h2>This profile is currently unavailable.</h2><p>You can explore other artists while this profile is paused.</p>${a('artists','Explore artists','btn primary')}</div></main>`;return `<main class="content">${a('artists','← Back to artists','back')}<div class="identity"><div class="initial">${e(x.name.slice(0,1))}</div><div><div class="eyebrow">${e(x.label)}</div><h1>${e(x.name)}</h1><p>${e(x.area)}, ${e(x.city)} · ${x.home?'Studio & home service':'Studio appointments'}</p></div></div>${artistProof(x)}${publicPortfolio(x)}<div class="split"><div class="stack">${x.id===0?instagramPanel(true):''}<div class="card"><h2>About the artist</h2><p style="margin-top:14px">${e(x.about)}</p><div class="chips" style="margin-top:19px">${x.styles.map(t=>tag(t)).join('')}</div><div class="display-only">Sample portfolio · actual healed-work photos are part of the launch profile requirements.</div></div><div class="card"><h2>Appointments</h2>${studioLocationPanel(x)}${row('Home service',x.home?'Available':'Not offered')}${row('Availability','Artist confirms the session time after consultation')}${x.home?`${row('Home-service areas',e(hc.areas))}${row('Indicative travel charge',money(hc.travel))}<p class="small" style="margin-top:12px">${e(hc.note)} Final travel charges are confirmed in your quote.</p>`:''}</div><div class="card"><h2>Client reviews</h2>${S.bookings.filter(b=>b.artist===x.id&&b.review).length?S.bookings.filter(b=>b.artist===x.id&&b.review).map(b=>`<div class="list-item"><div><strong>${'★'.repeat(b.review.rating)}</strong> ${tag('Linked to booking','green')}<p>${e(b.review.text||'Rating shared by client.')}</p></div></div>`).join(''):'<p style="margin-top:14px">No completed-booking reviews yet.</p>'}</div></div><aside class="card sticky"><p class="small">Starting price</p><div class="price" style="margin:8px 0">${money(x.starting)}</div><p class="small">The final quote depends on design, size and placement.</p><hr class="rule">${btn('new-enquiry','Enquire about my tattoo','btn primary full',`data-id="${x.id}"`)}<div style="margin-top:10px">${btn('save-artist',S.saved.includes(x.id)?'Saved ♥':'Save artist ♡','btn full',`data-id="${x.id}"`)}</div><p class="help">Share your idea first. No booking is confirmed until you accept the quote.</p></aside></div></main>`;}

const SIZE_PRESETS=[
 'Size of a credit card 💳',
 'Palm-sized ✊',
 'Hand-sized 🖐',
 'Half sleeve or larger 😎',
 'Haven’t decided yet 🧐'
];
function sizePicker(size){
 const selected=SIZE_PRESETS.includes(size)?size:SIZE_PRESETS[4];
 return `<div class="field"><div class="label" id="tattoo-size-label">Approximate size</div><p class="help">Choose the closest match. Your artist will confirm the dimensions with you.</p><div class="size-options size-options-simple" role="group" aria-labelledby="tattoo-size-label">${SIZE_PRESETS.map(name=>btn('size',`<strong>${e(name)}</strong>`,'size-choice',`data-value="${e(name)}" aria-pressed="${name===selected}"`)).join('')}</div><input type="hidden" name="size" value="${e(selected)}"></div>`;
}
function choosePlacement(value){
 S.draft.placement=value;save();
 const input=document.querySelector('input[name="placement"]');if(input)input.value=value;
 const label=document.querySelector('[data-placement-label]');if(label)label.textContent=value;
 document.querySelectorAll('[data-action="placement"]').forEach(part=>part.setAttribute('aria-pressed',String(part.dataset.value===value)));
 const list=document.querySelector('[data-placement-select]');if(list)list.value=value;
}
function chooseSize(value){
 S.draft.size=value;save();
 const input=document.querySelector('input[name="size"]');if(input)input.value=value;
 document.querySelectorAll('[data-action="size"]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.value===value)));
}
function updateLocality(service){
 const holder=document.querySelector('[data-locality-container]');
 const input=document.querySelector('input[name="area"]');
 if(holder)holder.hidden=service!=='home';
 if(input){input.required=service==='home';input.disabled=service!=='home';}
}

function enquiryPage(){
 const d=S.draft,x=selectedArtist();let body='';
 if(!x.home&&d.service==='home')d.service='studio';
 if(enquiryStep===1)body=`${textField('What would you like to get tattooed?','idea',d.idea,'A short description is enough. You can refine it with the artist.',true)}<div class="field"><label class="label" for="reference-file">Reference images <span class="muted">(optional)</span></label><div class="file-box"><input id="reference-file" type="file" name="referenceFile" accept="image/*"><p class="help">Preview only. Your file is not uploaded to a server.</p>${referenceURL?`<img class="upload-thumb" src="${referenceURL}" alt="Your selected reference">`:''}<p class="help" data-filename>${e(d.reference)}</p></div></div>`;
 if(enquiryStep===2)body=`<div class="details-choice-grid">${TattooBodyMap.render(d.placement,bodyView)}<div>${sizePicker(d.size)}${selectField('Your budget','budget',['Not sure yet','Under ₹5,000','₹5,000–₹10,000','₹10,000–₹15,000','₹15,000–₹25,000','₹25,000+'],d.budget)}</div></div>`;
 if(enquiryStep===3)body=`<div class="field"><label class="label" for="f-service">Appointment location</label><select id="f-service" name="service"><option value="studio" ${d.service==='studio'?'selected':''}>At the artist’s studio</option>${x.home?`<option value="home" ${d.service==='home'?'selected':''}>At my place</option>`:''}</select></div><div data-locality-container ${d.service==='studio'?'hidden':''}>${formField('Your locality','area',d.area,'text','Required for home service so the artist can confirm coverage.',d.service==='home')}</div>${selectField('When would you like it?','datePreference',['Flexible','This week','Next week','This month'],d.datePreference)}<div class="note">The artist will discuss your design and send a quote. Your appointment is confirmed after you accept the final details.</div>`;
 return `<main class="content ${enquiryStep===2?'enquiry-details':'tiny'}">${a('profile','← Back to artist','back')}<div class="step-label">Step ${enquiryStep} of 3 · ${e(x.name)}</div><div class="progress">${[1,2,3].map(n=>`<span class="${n<=enquiryStep?'done':''}"></span>`).join('')}</div>${head('Your tattoo idea',['Tell us your idea.','A few useful details.','Where and when?'][enquiryStep-1])}<form data-form="enquiry" class="card">${body}<div class="error" role="alert" data-error hidden></div><div class="actions" style="margin-top:24px">${enquiryStep>1?btn('enquiry-back','Back'):''}<button class="btn primary" type="submit">${enquiryStep===3?'Send enquiry →':'Continue →'}</button></div><p class="help">Your draft stays on this browser when you go back.</p></form></main>`;
}
function loginPage(){return `<main class="content tiny">${a(S.draft.awaitingSignIn?'enquiry':'home','← Back','back')}${S.draft.awaitingSignIn?'<p class="login-context">Your tattoo idea is saved. Sign in to send it to your artist.</p>':''}${signInCard()}</main>`;}
function finishDemoSignIn(method){
 S.client.signedIn=true;S.client.authMethod=method;
 if(method==='phone')S.client.phone=authPreview.phone;
 authPreview={step:'phone',phone:'',expires:0,attempts:0};
 save();if(S.draft.awaitingSignIn)sendEnquiry();else{const target=S.authReturn||'home';delete S.authReturn;save();go(target);render();toast('Signed in to the demo.');}
}

function bookingList(items,to){return items.length?`<div class="card list">${items.map(b=>`<div class="list-item"><div class="request-row"><img src="${e(b.referenceImage||artistFor(b).image)}" alt="Tattoo reference"><div class="row-main"><div class="actions">${tag(names[b.status],['completed','reviewed','confirmed'].includes(b.status)?'green':'')}${tag(b.id)}</div><h3 style="margin-top:8px">${e(b.idea.slice(0,65))}${b.idea.length>65?'…':''}</h3><p>${e(artistFor(b).name)} · ${b.service==='home'?'Home visit':'Studio'}${b.quote?' · '+e(formatDate(b.quote.date)):''}</p></div></div>${bookingLink(to.startsWith('artist-')?to:'booking',b,to.startsWith('artist-')?'Open enquiry →':'Open tattoo →','btn compact')}</div>`).join('')}</div>`:`<div class="card empty"><h2>Nothing here yet.</h2><p>Your enquiries and appointment updates will appear here.</p>${a('artists','Explore artists','btn primary')}</div>`;}
function requestsPage(){return `<main class="content narrow">${head('Every tattoo, one place','My tattoos','Your ideas, conversations, quotes and appointments.')}<div class="stack">${notificationsPanel()}${bookingList(S.bookings,'booking')}</div></main>`;}

function formatDate(d){try{return new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00'));}catch{return d;}}
function brief(b,after=''){return `<div class="card"><div class="section-head"><h2>Tattoo brief</h2>${tag(b.id)}</div><p>${e(b.idea)}</p><hr class="rule">${row('Placement',e(b.placement||'Not sure yet'))}${row('Size',e(b.size||'Not sure yet'))}${row('Budget',e(b.budget))}${row('Appointment',b.service==='home'?'At client’s place':'At the studio')}${row('Locality',e(b.area))}${row('Preferred timing',e(b.datePreference||'Flexible'))}${b.referenceImage?`<div class="reference-grid" style="margin-top:16px"><img src="${e(b.referenceImage)}" alt="Tattoo reference"></div>`:''}${b.reference?`<p class="help">Reference: ${e(b.reference)}</p>`:''}${after}</div>`;}

function chatKey(booking,sender){return booking+'|'+sender;}
function chatDraft(booking,sender){const key=chatKey(booking,sender);if(!chatDrafts.has(key))chatDrafts.set(key,{text:'',images:[]});return chatDrafts.get(key);}
function chatIsOpen(booking,sender){return currentBooking()?.id===booking&&(sender==='artist'?route()==='artist-enquiry':['booking','conversation','quote','advance','appointment'].includes(route()));}
function messages(b,artist=false){
 const sender=artist?'artist':'client',draft=chatDraft(b.id,sender);
 return `<div class="card chat-card"><div class="section-head"><h2>Conversation</h2><span class="small">${e(b.id)}</span></div><div class="messages">${b.messages.map(m=>`<div class="message ${m.from===sender?'mine':''} ${m.kind==='aftercare'?'aftercare-message':''}"><small>${m.from==='artist'?'Artist':'Client'}${m.kind==='aftercare'?' · Aftercare':''}</small>${m.text?`<p>${e(m.text)}</p>`:''}${m.attachments?.length?`<div class="chat-message-images">${m.attachments.map(im=>`<button type="button" class="chat-image-button" data-action="view-chat-image" data-media="${e(im.id)}" data-name="${e(im.name)}" aria-label="Enlarge ${e(im.name)}"><span class="chat-image-frame"><img data-media-id="${e(im.id)}" alt="${e(im.name)}" loading="lazy"><span class="chat-image-loading">Loading image…</span></span><span class="chat-image-caption">${e(im.name)}</span></button>`).join('')}</div>`:''}</div>`).join('')}</div>${artist?`<div class="quick-replies">${S.savedReplies.map((text,i)=>btn('saved-reply',e(text.slice(0,48))+(text.length>48?'…':''),'chip',`data-index="${i}" data-booking="${e(b.id)}"`)).join('')}</div>`:''}<form class="chat-composer" data-form="message" data-booking="${e(b.id)}"><div class="chat-pending-images" aria-live="polite">${draft.images.map((im,i)=>`<div class="chat-pending-image"><img src="${im.url}" alt="Selected image: ${e(im.file.name)}">${btn('remove-chat-image','×','chat-remove-image',`data-index="${i}" data-booking="${e(b.id)}" data-sender="${sender}" aria-label="Remove ${e(im.file.name)}"`)}<span>${e(im.file.name)}</span></div>`).join('')}</div><div class="chat-composer-row"><input id="message-input" name="message" aria-label="Message or image caption" placeholder="${draft.images.length?'Add a caption (optional)…':'Write a message…'}" value="${e(draft.text)}" maxlength="1500"><button class="btn primary" type="submit">Send</button></div><div class="chat-composer-tools">${btn('pick-chat-images','+ Add images','btn compact',`data-booking="${e(b.id)}" aria-label="Import images for this conversation"`)}<input id="chat-images" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden aria-label="Choose chat images"><span class="help">JPG, PNG, WebP or GIF · up to 4 images · 5 MB each</span></div><input type="hidden" name="sender" value="${sender}"><div class="error" data-error role="alert" hidden></div></form><p class="help">Preview conversation · signed-in workspace data syncs across your devices when connected. No external messages are sent.</p></div>`;
}
async function hydrateChatImages(){
 for(const image of document.querySelectorAll('img[data-media-id]')){
  const frame=image.closest('.chat-image-frame');
  try{const url=await ChatMedia.resolve(image.dataset.mediaId);if(image.isConnected===false)continue;image.onload=()=>{const loading=frame?.querySelector('.chat-image-loading');if(loading)loading.hidden=true;};image.onerror=()=>{image.hidden=true;const loading=frame?.querySelector('.chat-image-loading');if(loading)loading.textContent='Image unavailable';};image.src=url;}
  catch{image.hidden=true;const loading=frame?.querySelector('.chat-image-loading');if(loading)loading.textContent='Image unavailable in this browser';}
 }
}
function stageChatImages(input){
 const form=input.closest('[data-form="message"]'),booking=form.dataset.booking,sender=form.querySelector('[name="sender"]').value,draft=chatDraft(booking,sender);
 try{const files=ChatMedia.validateFiles(input.files,draft.images.length);files.forEach(file=>draft.images.push({file,url:URL.createObjectURL(file)}));if(chatIsOpen(booking,sender))render();}
 catch(err){formError(form,err);input.value='';}
}
async function sendChatMessage(form,b,fd){
 if(form.dataset.busy==='true')return;
 const sender=fd.get('sender');if(!['client','artist'].includes(sender))throw Error('Select a valid conversation role.');
 const text=String(fd.get('message')||'').trim(),draft=chatDraft(b.id,sender),images=[...draft.images];
 if(!text&&!images.length)throw Error('Write a message or add an image first.');
 form.dataset.busy='true';const controls=[...form.querySelectorAll('button,input')];controls.forEach(el=>el.disabled=true);const send=form.querySelector('button[type="submit"]');if(send)send.textContent='Sending…';
 let attachments=[];
 try{
  attachments=await ChatMedia.put(images.map(im=>im.file));
  const message={from:sender,text,at:Date.now(),...(attachments.length?{attachments}:{})};b.messages.push(message);if(sender==='artist'&&!b.firstArtistReplyAt)b.firstArtistReplyAt=Date.now();
  if(!save()){b.messages.pop();await ChatMedia.remove(attachments.map(im=>im.id));throw Error('Your message could not be saved. Try again before leaving this page.');}
  images.forEach(im=>URL.revokeObjectURL(im.url));draft.images=[];draft.text='';if(chatIsOpen(b.id,sender))render();toast(attachments.length?'Images added to the demo conversation.':'Demo message saved.');
 }catch(err){if(attachments.length&&!b.messages.some(m=>m.attachments?.some(im=>im.id===attachments[0].id)))await ChatMedia.remove(attachments.map(im=>im.id)).catch(()=>{});throw err;}
 finally{form.dataset.busy='false';controls.forEach(el=>el.disabled=false);if(send)send.textContent='Send';}
}
async function showChatImage(id,name){
 try{
  const url=await ChatMedia.resolve(id);document.querySelector('.modal-overlay')?.remove();const wrap=document.createElement('div');wrap.className='modal-overlay';wrap.innerHTML=`<section class="modal chat-image-modal" role="dialog" aria-modal="true" aria-label="Image preview"><button type="button" class="close" aria-label="Close image preview" data-action="close-modal">×</button><h2>${e(name)}</h2><img src="${url}" alt="${e(name)}"><a class="btn" href="${url}" download="${e(name)}">Download image</a></section>`;document.body.append(wrap);wrap.querySelector('.close').focus();wrap.addEventListener('keydown',ev=>{if(ev.key==='Escape')wrap.remove();if(ev.key==='Tab'){const controls=[...wrap.querySelectorAll('button,a')],first=controls[0],last=controls.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
 }catch(err){toast(err.message);}
}

function conversationPage(artist=false){const b=currentBooking();if(!b)return missing();return `${head(artist?'Client enquiry':'Your request',artist?e(b.client):e(artistFor(b).name),`${b.id} · ${names[b.status]}`,tag(names[b.status],b.status==='confirmed'?'green':''))}<div class="split"><div class="stack">${brief(b)}${messages(b,artist)}</div><aside class="card sticky"><h2>Next step</h2><p style="margin:14px 0 20px">${b.status==='requested'?(artist?'Discuss the brief, then send a clear quote.':'Your enquiry is with the artist. Discuss the details before booking.'):b.status==='quoted'?(artist?'The client can now review and accept your quote.':'Your artist has sent a quote. Review the date, price and location.'):b.status==='cancelled'?'This enquiry has been cancelled.':'Your appointment details are ready.'}</p>${artist?(b.status==='quoted'&&M.advancePaid(b)?a('artist-booking','View quote & advance','btn primary full'):['requested','quoted'].includes(b.status)?`${a('artist-quote',b.status==='quoted'?'Edit & resend quote':'Create quote','btn primary full')}<div style="margin-top:12px">${btn('cancel-booking','Decline enquiry','btn full danger')}</div>`:a('artist-booking','View appointment','btn primary full')):(b.status==='quoted'?a('quote','Review quote','btn primary full'):['confirmed','started','completed','reviewed'].includes(b.status)?a('appointment','View appointment','btn primary full'):b.status==='cancelled'?(b.advance?a('appointment','View booking & payment','btn primary full'):a('artists','Explore artists','btn full')):tag('Waiting for artist'))}${a('help','Get help','btn ghost full')}</aside></div>`;}

function updateAdvanceFields(enabled){
 const holder=document.querySelector('[data-advance-fields]');if(holder)holder.hidden=!enabled;
 for(const name of ['advanceAmount','advancePolicy']){const input=document.querySelector('[name="'+name+'"]');if(input){input.required=enabled;input.disabled=!enabled;}}
}

function quoteSummary(b){
 const q=b.quote;if(!q)return '<p>No quote has been sent yet.</p>';
 const advance=M.requiredAdvance(q),paid=M.advancePaid(b),refunded=b.advance?.status==='refunded';
 return `${row('Tattoo',money(q.amount))}${row('Travel charge',money(q.travel))}<hr class="rule">${row('Total agreed amount',money(M.totalAmount(q)))}${advance?`${row(refunded?'Advance refunded':paid?'Advance paid':'Advance to book',money(advance))}${b.status!=='cancelled'?row(paid?'Balance due at appointment':'Balance after advance',money(paid?M.balanceDue(b):M.totalAmount(q)-advance)):''}<p class="help">The advance is part of your total, not an extra charge.</p>`:''}${row('Date',e(formatDate(q.date)))}${row('Time',e(q.time))}${row('Appointment',b.service==='home'?'Home visit':'Studio appointment')}${row('Location',e(b.service==='home'?b.address||b.area:q.location||artistFor(b).area))}${studioQuoteLink(b)}${advance&&q.advanceTerms?`<hr class="rule"><h3 style="font-size:14px">Advance cancellation & rescheduling</h3>${M.advancePolicy(q.advancePolicy)?`<p class="small" style="margin-top:8px"><strong>${e(M.advancePolicy(q.advancePolicy).title)}</strong></p>`:''}<p class="small advance-policy-terms" style="margin-top:8px">${e(q.advanceTerms)}</p>`:''}${q.notes?`<hr class="rule"><p class="small">${e(q.notes)}</p>`:''}`;
}
function quotePage(){
 const b=currentBooking();if(!b||!b.quote)return `<main class="content tiny"><div class="card empty"><h2>No quote yet.</h2><p>The artist sends a quote after discussing your idea.</p>${a('conversation','Open conversation','btn primary')}</div></main>`;
 if(b.status==='cancelled')return `<main class="content narrow">${head('Booking cancelled','This appointment is cancelled.','Your quote and any advance payment remain in the booking record.')}<div class="card">${quoteSummary(b)}<div style="margin-top:20px">${a('appointment','View cancellation details','btn primary')}</div></div></main>`;
 const due=M.requiredAdvance(b.quote),paid=M.advancePaid(b),needsPayment=due>0&&!paid;
 return `<main class="content narrow">${a('conversation','← Conversation','back')}${head('Before you book','Review your appointment.',needsPayment?'Review once. A successful advance payment confirms your appointment.':'Check the price, place and timing together.')}<div class="split"><div class="card"><h2>${e(artistFor(b).name)}</h2><div style="margin-top:18px">${quoteSummary(b)}</div></div><div class="card"><form data-form="accept-quote" data-booking="${e(b.id)}">${paid?`<div class="note success"><strong>Advance paid: ${money(due)}</strong><br>Receipt ${e(b.advance.receipt)}. Confirm the appointment below.</div>`:needsPayment?`<div class="note"><strong>${money(due)} advance required to book.</strong><br>This is deducted from the total. Your booking is confirmed as soon as payment succeeds.</div>`:'<div class="note">This artist does not require an advance for this appointment.</div>'}${b.service==='home'?`<div style="margin-top:20px">${textField('Address for the home visit','address',b.address,'Share the full address when arranging this appointment.',true)}</div><p class="help">The artist confirms the appointment setup during consultation.</p>`:''}<label class="inline-field" style="margin:20px 0"><input type="checkbox" name="agreed" required><span>${needsPayment?'I agree to the quote and advance terms. Payment will confirm my booking.':'I agree to the amount, date and location.'}</span></label><div class="error" data-error role="alert" hidden></div><button type="submit" class="btn primary full" ${b.status!=='quoted'?'disabled':''}>${b.status!=='quoted'?'Quote already accepted':needsPayment?'Continue to payment →':'Accept & confirm appointment'}</button></form>${a('conversation','Ask the artist a question','btn ghost full')}<p class="help">Design preview: advance payments are simulated. No money is transferred.</p></div></div></main>`;
}
function advancePage(){
 const b=currentBooking();if(!b||!b.quote||!M.requiredAdvance(b.quote))return `<main class="content tiny"><div class="card empty"><h2>No advance is needed.</h2><p>You can accept your quote directly.</p>${a('quote','Review quote','btn primary')}</div></main>`;
 const due=M.requiredAdvance(b.quote),paid=M.advancePaid(b);
 if(paid)return `<main class="content tiny"><div class="card"><div class="success-mark">✓</div><h1 style="font-size:30px">${b.status==='quoted'?'Advance recorded.':'Your appointment is booked.'}</h1>${row('Receipt',e(b.advance.receipt))}${row('Paid now',money(due))}${row('Balance due at appointment',money(M.balanceDue(b)))}<div style="margin-top:20px">${a(b.status==='quoted'?'quote':'appointment',b.status==='quoted'?'Review appointment':'View appointment','btn primary full')}</div><p class="help">Demo payment · no money transferred.</p></div></main>`;
 if(b.status!=='quoted'||b.advance?.status==='refunded')return `<main class="content tiny"><div class="card empty"><h2>This payment is not available.</h2><p>The booking is no longer waiting for an advance.</p>${a('appointment','View booking','btn primary')}</div></main>`;
 if(b.bookingConsent!==JSON.stringify(b.quote))return `<main class="content tiny"><div class="card"><h2>Review your quote first.</h2><p style="margin:14px 0 20px">Check the price, appointment details and advance terms before paying.</p>${a('quote','Review quote','btn primary full')}</div></main>`;
 return `<main class="content tiny">${a('quote','← Back to quote','back')}${head('Book your appointment','Pay the booking advance.',`${e(artistFor(b).name)} · ${e(b.id)}`)}<form class="card" data-form="pay-advance" data-booking="${e(b.id)}"><div class="payment-amount"><span class="small">Due now</span><div class="price">${money(due)}</div><p class="small">Part of your ${money(M.totalAmount(b.quote))} total.</p></div><hr class="rule">${row('Advance',money(due))}${row('Balance after advance',money(M.totalAmount(b.quote)-due))}${row('Appointment',e(formatDate(b.quote.date))+' · '+e(b.quote.time))}<div class="note" style="margin:20px 0">Demo payment. No UPI, card or bank details are needed. A successful payment credits the artist’s wallet once.</div>${b.lastAdvanceAttempt==='failed'?'<div class="error" role="alert">Payment did not go through. No money was credited. You can retry.</div>':''}<div class="error" data-error role="alert" hidden></div><button type="submit" class="btn primary full">Pay ${money(due)} & confirm booking (demo)</button><div style="margin-top:12px">${btn('advance-payment-fail','Try a failed payment','btn ghost full')}</div><p class="help">Payment success = appointment confirmed. No extra booking step.</p></form></main>`;
}
function statusPath(b){return `<div class="status-path" aria-label="Booking progress">${['requested','quoted','confirmed','started','completed'].map(k=>`<span class="${b.status===k||(b.status==='reviewed'&&k==='completed')?'current':''}">${names[k]}</span>`).join('')}${b.status==='cancelled'?tag('Cancelled','red'):''}</div>`;}

function artistSessionActions(b,detail=false){
 let main='';
 if(b.status==='confirmed')main=bookingLink('artist-start',b,'Start session →','btn primary');
 else if(b.status==='started')main=bookingLink('artist-complete',b,'Mark session completed','btn primary');
 else if(['requested','quoted'].includes(b.status))main=bookingLink('artist-enquiry',b,'Open enquiry','btn primary');
 else main=tag(names[b.status],['completed','reviewed'].includes(b.status)?'green':'');
 return `<div class="ticket-session-actions" data-session-actions="${e(b.id)}"><div class="ticket-action-label"><strong>Session actions</strong><span>${e(b.id)} · ${e(b.client)}</span></div><div class="actions">${main}${!detail?bookingLink('artist-booking',b,['completed','reviewed'].includes(b.status)&&!b.aftercare?'Send aftercare →':'View booking details','btn'):bookingLink('artist-enquiry',b,'Open conversation','btn')}${detail&&['requested','quoted','confirmed'].includes(b.status)?btn('cancel-booking','Cancel booking','btn danger',`data-booking="${e(b.id)}"`):''}${detail&&b.status==='cancelled'&&b.advance?.status==='paid'&&!b.charged?btn('refund-advance','Refund advance (demo)','btn',`data-booking="${e(b.id)}"`):''}</div>${detail&&b.status==='confirmed'?`<div class="actions" style="margin-top:14px">${bookingLink('artist-reschedule',b,'Propose a new time','btn compact')}${a('artist-new-booking?from='+encodeURIComponent(b.id),'Add next session','btn compact')}${btn('copy-link','Copy client link','btn compact',`data-url="${e(directURL(b))}"`)}</div>`:''}${detail&&b.charged?`<div class="help">Commission recorded for ${e(b.id)}: ${money(b.commission)}</div>`:''}</div>`;
}
function artistBookingDetails(b){
 return `${a('artist-bookings','← Back to bookings','back')}${head('Your appointment',e(b.id),`Client: ${e(b.client)}`,tag(names[b.status],['confirmed','completed','reviewed'].includes(b.status)?'green':''))}${statusPath(b)}<div class="stack artist-booking-detail">${brief(b,artistSessionActions(b,true))}${artistAftercarePanel(b)}${projectPanel(b,true)}<div class="card"><h2>Appointment & payment details</h2><div style="margin-top:18px">${quoteSummary(b)}</div>${b.advance?.status==='paid'?`<div class="note ${b.status==='cancelled'?'warning':'success'}" style="margin-top:18px">Advance paid: ${money(b.advance.amount)} · Receipt ${e(b.advance.receipt)}${b.status==='cancelled'?'<br>Any refund follows the terms agreed with the client.':''}</div>`:b.advance?.status==='refunded'?`<div class="note success" style="margin-top:18px">Advance refunded: ${money(b.advance.amount)} (demo)</div>`:''}</div></div>`;
}
function artistBookingTicket(b){
 return `<article class="card booking-ticket" data-booking-ticket="${e(b.id)}"><div class="booking-ticket-header"><div><span class="eyebrow">${e(b.id)}</span><h2>${e(b.client)}</h2></div>${tag(names[b.status],['confirmed','completed','reviewed'].includes(b.status)?'green':'')}</div><div class="ticket-brief"><div><h3>Tattoo brief</h3><p>${e(b.idea)}</p><div class="ticket-meta"><span>${e(b.placement||'Placement to confirm')}</span><span>${e(b.size||'Size to confirm')}</span><span>${b.service==='home'?'Home visit':'Studio appointment'}</span>${b.quote?`<span>${e(formatDate(b.quote.date))} · ${e(b.quote.time)} IST</span>`:''}</div></div>${b.referenceImage?`<img src="${e(b.referenceImage)}" alt="Tattoo reference for ${e(b.id)}">`:''}</div>${artistSessionActions(b)}</article>`;
}

function appointmentPage(artist=false){const b=currentBooking();if(!b)return missing();if(artist)return artistBookingDetails(b);return `${head(artist?'Manage appointment':'Your appointment',e(b.id),`${e(artist?'Client: '+b.client:artistFor(b).name)}`,tag(names[b.status],['confirmed','completed','reviewed'].includes(b.status)?'green':''))}${b.status==='confirmed'?'<div class="note success booking-confirmation" role="status" style="margin-bottom:22px"><strong>You’re booked.</strong> Your appointment is confirmed. All the details are below.</div>':''}${statusPath(b)}<div class="split"><div class="stack"><div class="card"><h2>Appointment details</h2><div style="margin-top:18px">${quoteSummary(b)}</div></div>${brief(b)}${['completed','reviewed'].includes(b.status)?`<div class="card"><h2>Aftercare & follow-up</h2><p style="margin-top:12px">${e(b.aftercare||'Follow the aftercare instructions provided by your artist. Contact them if you have questions about your tattoo.')}</p></div>`:''}</div><aside class="card sticky"><h2>${artist?'Session actions':'What happens next?'}</h2><p style="margin:14px 0 22px">${b.status==='confirmed'?(artist?'Ask the client for their booking code at the start of the session.':'At your appointment, show the booking code after checking the final details.'):b.status==='started'?'Your session has been started. The artist will mark it completed afterwards.':b.status==='completed'?'Your tattoo appointment is complete. You can now share your experience.':b.status==='reviewed'?'Thank you for reviewing your experience.':b.status==='cancelled'?'This appointment was cancelled.':'Discuss your idea and accept a quote before starting a session.'}</p>${artist?(b.status==='confirmed'?a('artist-start','Start session','btn primary full'):b.status==='started'?a('artist-complete','Mark session completed','btn primary full'):['requested','quoted'].includes(b.status)?a('artist-enquiry','Open enquiry','btn primary full'):tag(names[b.status])):(b.status==='confirmed'?`<div class="note"><span class="small">Start-session code · demo</span><div class="price" style="margin:7px 0">123456</div><span class="small">Share at the appointment, before tattooing starts.</span></div>`:b.status==='completed'?a('review','Leave a review','btn primary full'):b.status==='quoted'?a('quote','Review quote','btn primary full'):tag(names[b.status]))}${['requested','quoted','confirmed'].includes(b.status)?`<div style="margin-top:14px">${btn('cancel-booking','Cancel appointment','btn full danger')}</div>`:''}${b.advance?.status==='paid'?`<hr class="rule"><div class="note ${b.status==='cancelled'?'warning':'success'}"><strong>Advance paid: ${money(b.advance.amount)}</strong><br>${b.status==='cancelled'?'Any refund follows the terms agreed with your artist.':'Receipt '+e(b.advance.receipt)+'. Applied to your quoted total.'}</div>${artist&&b.status==='cancelled'&&!b.charged?`<div style="margin-top:12px">${btn('refund-advance','Refund advance (demo)','btn full')}</div>`:''}`:b.advance?.status==='refunded'?`<hr class="rule"><div class="note success">Advance refunded: ${money(b.advance.amount)} (demo)</div>`:''}${a(artist?'artist-enquiry':'conversation','Open conversation','btn ghost full')}${a('help','Need help?','btn ghost full')}${artist&&b.charged?`<hr class="rule">${row('Commission recorded',money(b.commission))}`:''}</aside></div>`;}
function appointmentsPage(){return requestsPage();}

function reviewPage(){const b=currentBooking();if(!b||!['completed','reviewed'].includes(b.status))return `<main class="content tiny"><div class="card empty"><h2>Review after your session.</h2><p>The artist needs to mark the appointment completed first.</p>${a('appointment','Appointment details','btn primary')}</div></main>`;if(b.status==='reviewed')return `<main class="content tiny"><div class="card"><div class="success-mark">✓</div><h2>Your review is saved.</h2><p style="margin:15px 0">${'★'.repeat(b.review.rating)} · ${e(b.review.text)}</p>${a('profile','View artist profile','btn primary')}</div></main>`;return `<main class="content tiny">${head('Your experience','How did it go?',`Your review will be linked to booking ${b.id}.`)}<div class="card">${reviewForm(b)}</div></main>`;}

function savedPage(){const items=artists().filter(x=>S.saved.includes(x.id));return `<main class="content">${head('Your shortlist','Saved artists','Compare your favourites when you’re ready.')}<div class="grid">${items.map(artistCard).join('')}</div>${items.length?'':`<div class="card empty"><h2>Keep your favourites here.</h2><p>Tap the heart on an artist card to add them to your shortlist.</p>${a('artists','Explore artists','btn primary')}</div>`}</main>`;}
function accountPage(){if(!S.client.signedIn)return loginPage();return `<main class="content tiny">${head('Your details',S.client.signedIn?'My account':'Continue when you’re ready.','Browsing does not require an account.')}<form data-form="account" class="card">${formField('Name','name',S.client.name,'text','',true)}${formField('Email','email',S.client.email,'email','Optional in this demo. Avoid entering real contact details.')}<div class="note">Your private preview workspace uses server storage when connected. Google/SMS sign-in and payments are still demonstrations.</div><button class="btn primary full" type="submit" style="margin-top:20px">${S.client.signedIn?'Save demo details':'Continue in demo'}</button>${S.client.signedIn?`<div class="actions" style="margin-top:18px">${btn('export-workspace','Download my workspace','btn compact')}${btn('retry-sync','Retry sync','btn compact')}${btn('logout','Sign out of demo','btn ghost')}</div>`:''}</form></main>`;}
function helpPage(){const b=currentBooking();return `<main class="content narrow">${head('We’re here to help','Help & support','Start with your artist, or report an issue with a booking.')}<div class="split"><div class="card"><h2>Common questions</h2><details><summary>How is my appointment confirmed?</summary><p>Discuss your idea and review the quote. If an advance is required, agree to the terms and pay to confirm. Otherwise, confirm the quote directly. The session code is used only when the appointment starts.</p></details><details><summary>How does home service work?</summary><p>Choose an artist offering home visits in your area. The artist confirms travel charges and the appointment setup before you accept the quote.</p></details><details><summary>Can I cancel?</summary><p>You can cancel a demo enquiry or confirmed appointment before it starts. Once a session has started, use support to request review. If you paid an advance, see the terms on your quote. Cancellation does not automatically refund it; discuss a refund with the artist or contact support.</p></details><details><summary>Are the profiles verified?</summary><p>The demo illustrates an artist approval process. Portfolio review or an OTP does not by itself certify tattoo quality or safety. Specific checks and their meaning must be shown on the live platform.</p></details></div><form class="card" data-form="support"><h2>Report an issue</h2><div style="margin-top:20px">${selectField('Related booking','booking',['General question',...S.bookings.map(x=>x.id)],b?.id||'General question')}${selectField('Issue','issue',['Booking question','Cancellation','Artist did not arrive','Price disagreement','Session issue','Other'],'Booking question')}${textField('What happened?','details','','Use demo information only.',true)}</div><button class="btn primary full" type="submit">Create demo support request</button><p class="help">No message is sent to a real support team.</p></form></div></main>`;}
function artistWelcome(){return `<main class="content narrow">${head('For tattoo artists','Your art. Their next story.','Get discovered for the work you love to make.')}<div class="split"><div class="stack"><div class="card"><h2>A space for your work.</h2><p style="margin-top:14px">Show your style, connect with people who share your vision and turn their ideas into tattoos.</p><hr class="rule">${row('Your prices','Set by you')}${row('Home service','Your choice')}${row('Your portfolio','Your spotlight')}</div><div class="note">Build your profile in three simple steps: artist details, portfolio and appointment options.</div></div><aside class="card join-card"><span class="eyebrow">Make your mark</span><h2 style="margin-top:12px">Let’s get you started.</h2><p style="margin:14px 0 24px">Tell us about your work. Add your portfolio and choose where you’d like to tattoo.</p><div class="note artist-join-fee"><strong>₹100 per appointment booking.</strong><br>Charged once when the session starts. You choose your prices and whether to request an advance.</div>${a('artist-signup','Create my artist profile →','btn primary full')}${a('artist-dashboard','Explore demo workspace','btn ghost full')}</aside></div></main>`;}
function artistSignup(){return `<main class="content tiny">${head('Artist account','A simple start.','Your portfolio and services come next.')}<form class="card" data-form="artist-signup">${formField('Artist name','name',S.profile.name,'text','',true)}${formField('Studio / business name','studio',S.profile.studio,'text','Use your own name if you work independently.')}${formField('City','city',S.profile.city,'text','',true)}<div class="note"><strong>Platform fee: ₹100 per appointment booking.</strong><br>Charged once at session start, including bookings from your personal link. This is a demo signup; live contact verification is not connected.</div><button class="btn primary full" type="submit" style="margin-top:22px">Continue to profile setup →</button></form></main>`;}
function artistOnboarding(){
 const count=Object.values(S.setup).filter(Boolean).length;
 const sections=[['details','1','Artist details','Your name, styles, location and starting price.','artist-settings?setup=1'],['portfolio','2','Portfolio','Show designs, completed tattoos and healed work.','artist-portfolio?setup=1'],['appointments','3','Appointment options','Choose studio appointments and optional home visits.','artist-home?setup=1']];
 return `${head('Your artist profile','Make your work discoverable.','Three simple steps. Take your time—we’ll keep your progress.')}<div class="setup-progress"><div><strong>${count} of 3 sections ready</strong><span class="small">You can return to any section.</span></div><div class="setup-progress-track" role="progressbar" aria-label="Profile setup" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${count}"><span style="width:${count/3*100}%"></span></div></div><div class="stack"><div class="card setup-checklist">${sections.map(([key,num,title,description,url])=>`<div class="list-item"><div class="setup-section"><span class="setup-number ${S.setup[key]?'ready':''}">${S.setup[key]?'✓':num}</span><div><h3>${title}</h3><p>${description}</p></div></div>${a(url,S.setup[key]?'Review →':'Start →','btn compact')}</div>`).join('')}</div><div class="card"><h2>Ready to make your mark?</h2><p style="margin:14px 0 20px">Check your work and details, then submit your profile for review.</p>${S.profile.submitted&&!S.profile.approved?tag('Waiting for profile review'):S.profile.approved?`${tag('Demo profile approved','green')} ${a('artist-dashboard','Open workspace','btn compact')}`:btn('submit-profile','Submit my profile →','btn primary')}<p class="help">Your profile appears in search after approval.</p></div><div class="note artist-fee-note"><strong>Platform commission: ₹100 per booking.</strong><br>Fixed for every tattoo price. Recorded once when your client’s booking code starts the appointment. ${a('artist-wallet','View artist wallet →','')}</div></div>`;
}
function artistDashboard(){const open=S.bookings.filter(b=>['requested','quoted'].includes(b.status)),today=S.bookings.filter(b=>b.quote?.date===B.nowDate()&&['confirmed','started'].includes(b.status));return `${head('Artist workspace','Your inbox. Your next session.','Keep client conversations and upcoming work in view.',a('artist-new-booking','Create booking link →','btn primary'))}<div class="stats"><div class="card stat"><p>Open enquiries</p><div class="number">${open.length}</div></div><div class="card stat"><p>Sessions today</p><div class="number">${today.length}</div></div><div class="card stat"><p>Profile</p><div class="number" style="font-size:22px">${M.visible(S.profile,S.wallet)?'Visible':'Paused'}</div>${a('artist-onboarding','Profile checklist','small')}</div></div>${!M.visible(S.profile,S.wallet)?'<div class="note warning" style="margin-bottom:22px">Your profile is paused. Review approval, availability or wallet dues in your settings.</div>':''}<div class="tabs">${a('artist-dashboard','Enquiries','active')}${a('artist-bookings','Booked sessions','')}${a('artist-links','Your booking links','')}</div>${bookingList(open,'artist-enquiry')}${today.length?`<div class="section-head" style="margin-top:28px"><h2>Today’s sessions</h2>${a('artist-calendar','Calendar →','small')}</div><div class="stack">${today.map(artistBookingTicket).join('')}</div>`:''}`;}

function artistEnquiries(){return `${head('Your pipeline','Client enquiries','Read the brief, discuss the idea and send a quote.')}<div class="tabs">${a('artist-enquiries','All enquiries','active')}${a('artist-bookings','Confirmed bookings','')}</div>${bookingList(S.bookings.filter(b=>['requested','quoted','cancelled'].includes(b.status)),'artist-enquiry')}`;}
function artistQuote(){
 const b=currentBooking();if(!b)return missing();
 if(!['requested','quoted'].includes(b.status)||b.advance?.status==='paid')return `<div class="card empty"><h2>${b.advance?.status==='paid'?'An advance has been paid.':'This booking is already '+e(names[b.status].toLowerCase())+'.'}</h2><p>${b.advance?.status==='paid'?'This paid quote is locked. Resolve changes with the client before making a new offer.':'Accepted appointment details cannot be silently edited.'}</p>${a('artist-booking','View booking','btn primary')}</div>`;
 const q=b.quote||{duration:S.profile.schedule.defaultDuration,prep:S.profile.schedule.prep,amount:14000,travel:b.service==='home'?S.home.travel:0,date:B.nowDate(),time:'14:00',location:(b.artist===0?String(S.profile.studioAddress||'').replace(/\s+/g,' ').trim():'')||artistFor(b).area,advanceRequired:false,advanceAmount:2000,advancePolicy:'',notes:'Final design and placement will be agreed during consultation.'};
 return `${a('artist-enquiry','← Client enquiry','back')}${head('Clear details','Send an appointment quote.',`Booking ${b.id} · ${e(b.client)}`)}<div class="split"><form data-form="artist-quote" class="card">${S.quoteTemplates.length?`<div class="field"><label class="label" for="quote-template">Start from a template</label><select id="quote-template"><option value="">Choose a template (optional)</option>${S.quoteTemplates.map((t,i)=>`<option value="${i}">${e(t.title)}</option>`).join('')}</select></div>`:''}${formField('Tattoo amount (₹)','amount',q.amount,'number','The tattoo amount shown to your client. Your platform fee stays fixed at ₹100.',true)}${b.service==='home'?formField('Travel charge (₹)','travel',q.travel,'number','Shown separately to the client.'):''}<div class="advance-settings"><label class="inline-field"><input type="checkbox" name="advanceRequired" id="require-advance" ${q.advanceRequired?'checked':''}><strong>Require an advance to book</strong></label><p class="help">Your choice for each appointment. The advance goes to your artist wallet and counts toward the total.</p><div data-advance-fields ${q.advanceRequired?'':'hidden'}>${formField('Advance amount (₹)','advanceAmount',q.advanceAmount||2000,'number','Must be greater than zero and no more than the total quote.',!!q.advanceRequired)}${advancePolicyField(q,!!q.advanceRequired)}</div></div><div class="grid two">${formField('Date','date',q.date,'date','',true)}${formField('Time','time',q.time,'time','Times shown in India Standard Time.',true)}</div>${formField(b.service==='home'?'Service locality':'Studio location','location',b.service==='home'?b.area:q.location,'text','',true)}${textField('Design & appointment notes','notes',q.notes,'Use for the design and appointment. Advance terms follow the selected preset.')}<div class="error" data-error role="alert" hidden></div><button type="submit" class="btn primary full">${b.status==='quoted'?'Resend updated quote':'Send quote to client'}</button><p class="help">An updated quote needs client acceptance. A quote with a paid advance cannot be silently changed.</p></form><div class="stack">${brief(b)}<div class="note">The client reviews once and pays any required advance to confirm. You can save common quote starting points in ${a('artist-templates','templates','')}.</div></div></div>`;
}
function artistBookings(){const list=S.bookings.filter(b=>['confirmed','started','completed','reviewed'].includes(b.status));return `${head('Your appointments','Booked sessions','Each session action belongs to the tattoo brief directly above it.')}<div class="section-head"><h2>Your booking tickets</h2><span class="small">Times in IST</span></div>${list.length?`<div class="stack booking-ticket-list">${list.map(artistBookingTicket).join('')}</div>`:`<div class="card empty"><h2>No booked sessions yet.</h2><p>After a client accepts a quote, their ticket and session actions will appear here.</p>${a('artist-enquiries','Open enquiries','btn primary')}</div>`}`;}
function artistStart(){const b=currentBooking();if(!b||b.status!=='confirmed')return `<div class="card empty"><h2>${b?.charged?'This session has already started.':'A confirmed booking is required.'}</h2><p>Commission is recorded once per session.</p>${a('artist-booking','View booking','btn primary')}</div>`;const fee=M.BOOKING_FEE;return `<div class="content tiny" style="padding-top:0">${head('At the appointment','Confirm. Then begin.',`${b.id} · ${e(b.client)}`)}<form class="card" data-form="start" data-booking="${e(b.id)}"><h2>Check with your client</h2><div style="margin-top:14px">${quoteSummary(b)}</div><hr class="rule">${row('Fixed booking commission',money(fee))}${row('Wallet after this session',money(S.wallet.balance-fee))}<div class="note ${S.wallet.balance-fee<0?'warning':''}" style="margin:18px 0">${S.wallet.balance-fee<0?'This session can proceed. Your profile will pause in search until your wallet balance returns to zero or above.':'The commission is deducted from your artist wallet when the code is confirmed.'}</div>${formField('Client booking code','otp','','text','Demo code: 123456. The production code will be unique, expiring and tied to this booking.',true)}<label class="inline-field"><input type="checkbox" name="agreed" required><span>The client has checked the final price and appointment details.</span></label><div class="error" data-error role="alert" hidden></div><button class="btn primary full" style="margin-top:20px" type="submit">Confirm code & start session</button></form></div>`;}
function artistComplete(){const b=currentBooking();if(!b||b.status!=='started')return `<div class="card empty"><h2>Start the session first.</h2><p>Only a session in progress can be marked completed.</p>${a('artist-booking','View booking','btn primary')}</div>`;return `<div class="content tiny" style="padding-top:0">${head('Session complete','Finish the appointment.',`${b.id} · ${e(b.client)}`)}<form class="card" data-form="complete" data-booking="${e(b.id)}"><div class="note success">Commission already recorded: ${money(b.commission)}. Completing the session will not charge it again.</div><p style="margin:22px 0">After marking this session complete, choose an aftercare template to send to ${e(b.client)}.</p><label class="inline-field"><input type="checkbox" name="done" required><span>The tattoo session is completed.</span></label><div class="error" data-error role="alert" hidden></div><button class="btn primary full" style="margin-top:22px" type="submit">Mark completed</button><p class="help">A review prompt appears on the client’s screen after completion.</p></form></div>`;}
function walletPage(){return `${head('Commission & visibility','Your artist wallet.','Know what was charged and when.')}<div class="split"><div class="stack"><div class="card"><p class="small">Current balance</p><div class="wallet-value ${S.wallet.balance<0?'negative':''}">${money(S.wallet.balance)}</div>${tag(S.wallet.balance<0?'Profile paused':M.visible(S.profile,S.wallet)?'Profile visible':'Profile paused',S.wallet.balance<0?'red':M.visible(S.profile,S.wallet)?'green':'')}<p style="margin-top:15px">${S.wallet.balance<0?'Clear your dues to restore discovery. Existing appointments and conversations remain available.':'Client advances are credited here. Your fixed ₹100 platform commission is deducted once when a booking starts.'}</p></div><div class="card"><h2>Wallet activity</h2><p class="help">Booking advances, top-ups, refunds and platform fees are shown separately.</p><div style="margin-top:18px">${S.wallet.transactions.map(t=>`<div class="transaction"><div><strong>${e(t.label)}</strong><small>${e(t.booking||'Demo transaction')}${t.receipt?' · '+e(t.receipt):''}</small></div><strong style="color:${t.amount<0?'var(--brand)':'var(--green)'}">${t.amount<0?'−':'+'}${money(Math.abs(t.amount))}</strong></div>`).join('')}</div></div></div><form class="card" data-form="topup"><h2>${S.wallet.balance<0?'Clear your dues':'Add wallet funds'}</h2><p style="margin:14px 0 22px">Demo top-up only. No card, UPI or bank payment is processed.</p>${formField('Amount (₹)','amount',S.wallet.balance<0?Math.ceil(-S.wallet.balance):1000,'number','',true)}<div class="error" data-error role="alert" hidden></div><button class="btn primary full" type="submit">Add demo funds</button><hr class="rule"><p class="small">₹100 per booking, whatever the tattoo price or travel charge. The same fixed fee applies to studio appointments and home visits.</p></form></div>`;}
function instagramHandle(raw){
 const value=String(raw||'').trim();if(!value)return '';
 let handle=value.replace(/^@/,'');
 if(/^https?:\/\//i.test(value)){
  let url;try{url=new URL(value);}catch{throw Error('Enter an Instagram username or profile URL.');}
  if(!['instagram.com','www.instagram.com'].includes(url.hostname)||url.username||url.password)throw Error('Use an instagram.com profile link.');
  handle=url.pathname.replace(/^\/|\/$/g,'');
 }
 if(!/^[a-zA-Z0-9._]{1,30}$/.test(handle)||['p','reel','reels','explore','accounts','stories'].includes(handle.toLowerCase()))throw Error('Enter a valid Instagram username, such as @yourportfolio.');
 return handle;
}
function instagramPosts(raw){
 const lines=String(raw||'').split(/\n/).map(x=>x.trim()).filter(Boolean);
 if(lines.length>3)throw Error('Add up to three recent Instagram work links.');
 return [...new Set(lines.map(line=>{let url;try{url=new URL(line);}catch{throw Error('Enter a full Instagram post or reel URL.');}
 if(url.protocol!=='https:'||!['instagram.com','www.instagram.com'].includes(url.hostname)||url.username||url.password||!/^\/(p|reel|tv)\/[a-zA-Z0-9_-]+\/?$/.test(url.pathname))throw Error('Use an HTTPS Instagram post or reel link.');
 return 'https://www.instagram.com'+url.pathname.replace(/\/$/,'')+'/';}))];
}
function instagramPanel(publicView=false){
 const ig=S.profile.instagram||{handle:'',posts:[]};
 let handle='',posts=[];try{handle=instagramHandle(ig.handle);posts=instagramPosts((ig.posts||[]).join('\n'));}catch{}
 if(publicView)return handle?`<div class="card instagram-public"><div class="section-head"><h2>More work on Instagram</h2><span class="instagram-symbol" aria-hidden="true">◎</span></div><p>Explore ${e(S.profile.name)}’s portfolio and recent work.</p><a class="btn" href="https://www.instagram.com/${e(handle)}/" target="_blank" rel="noopener noreferrer">@${e(handle)} ↗</a>${posts.length?`<div class="instagram-recent"><h3>Recent work</h3>${posts.map((url,i)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">View work ${i+1} on Instagram ↗</a>`).join('')}</div>`:''}</div>`:'';
 return `<form class="card instagram-editor" data-form="instagram-portfolio"><div class="section-head"><div><span class="eyebrow">Your social portfolio</span><h2>Instagram</h2></div>${handle?tag('Profile linked','green'):tag('Optional')}</div><p>Let clients explore more of your work.</p><div class="field" style="margin-top:20px"><label class="label" for="instagram-handle">Username or profile link</label><input id="instagram-handle" name="instagram" value="${e(handle?'@'+handle:'')}" placeholder="@yourportfolio" autocomplete="off"></div>${textField('Recent work links (optional)','instagramPosts',posts.join('\n'),'Add up to 3 public Instagram posts or reels, one link per line.')}<p class="help">Links open Instagram. Recent work is updated by you; this preview does not sign in to Instagram or sync a feed.</p><div class="error" data-error role="alert" hidden></div><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">Save Instagram portfolio</button>${handle?`<a href="https://www.instagram.com/${e(handle)}/" class="btn" target="_blank" rel="noopener noreferrer">View @${e(handle)} ↗</a>${btn('disconnect-instagram','Remove link','btn ghost')}`:''}</div></form>`;
}
function pendingReview(){
 if(new URLSearchParams(location.hash.split('?')[1]||'').has('review')||!S.client.signedIn||route().startsWith('artist-')||route().startsWith('admin-')||['review','workflow','screens'].includes(route()))return null;
 return S.bookings.filter(b=>b.status==='completed'&&!b.review&&!b.reviewPromptDismissed&&b.client===S.client.name).sort((a,b)=>(b.completedAt||0)-(a.completedAt||0))[0]||null;
}
function reviewForm(b){return `<form data-form="review" data-booking="${e(b.id)}"><label class="label">Rate your experience</label><div class="stars" role="group" aria-label="Rating">${[1,2,3,4,5].map(n=>btn('rating','★',n<=rating?'chosen':'',`data-value="${n}" aria-label="${n} ${n===1?'star':'stars'}" aria-pressed="${n===rating}"`)).join('')}</div>${textField('Tell others about your experience','review',reviewDrafts.get(b.id)||'','Optional: consultation, communication and your appointment experience.')}<div class="error" role="alert" data-error hidden></div><button class="btn primary full" type="submit">Share review</button></form>`;}
function reviewPromptMarkup(){const b=pendingReview();return b?`<div class="modal-overlay review-overlay"><section class="modal review-modal" role="dialog" aria-modal="true" aria-labelledby="review-prompt-title" aria-describedby="review-prompt-description"><button class="close" data-action="review-later" data-review-booking="${e(b.id)}" aria-label="Review later">×</button><span class="eyebrow">Session complete</span><h2 id="review-prompt-title">How was your tattoo experience?</h2><p id="review-prompt-description">${e(artistFor(b).name)} marked ${e(b.id)} complete. Share your experience.</p>${reviewForm(b)}${btn('review-later','I’ll review later','btn ghost full',`data-review-booking="${e(b.id)}"`)}</section></div>`:'';}
function dismissReview(id){const b=S.bookings.find(b=>b.id===id);if(b){b.reviewPromptDismissed=true;rating=0;save();render();}}
function receiveSharedState(event){
 if(event.key!==KEY||!event.newValue||event.newValue===lastObservedStorage)return;
 try{const next=JSON.parse(event.newValue);if(!next.profile||!Array.isArray(next.bookings))return;
 lastObservedStorage=event.newValue;const ownSelection=S.selectedBooking,ownArtist=S.selectedArtist,ownDraft=S.draft;
 S={...next,selectedBooking:ownSelection,selectedArtist:ownArtist,draft:ownDraft};render();
 }catch{}
}

function portfolioPage(){return portfolioManager();}

function homeSettings(){return `${setupBack()}${head('Your services','Home visits, on your terms.','Turn on home service only in the areas you want to cover.')}<form class="card" data-form="home-settings"><label class="inline-field" style="margin-bottom:25px"><input type="checkbox" name="enabled" ${S.home.enabled?'checked':''}><strong>Home service available</strong></label><div class="grid two">${formField('Service areas','areas',S.home.areas,'text','Comma-separated localities, shown on your profile.',true)}${formField('Maximum travel distance (km)','radius',S.home.radius,'number','Indicative. Confirm the specific address before booking.',true)}${formField('Indicative travel charge (₹)','travel',S.home.travel,'number','The final charge is shown separately in each quote.',true)}</div>${textField('Home-visit details','note',S.home.note,'Let clients know what needs to be agreed during consultation.')}<div class="note">When turned off, your profile is excluded from home-service-only searches. Existing bookings are kept; discuss any changes with those clients.</div><div class="error" data-error role="alert" hidden></div><button class="btn primary" style="margin-top:22px" type="submit">${inProfileSetup()?'Save & return to profile setup':'Save home-service settings'}</button></form>`;}
function googleBusinessLink(raw){
 const value=String(raw||'').trim();if(!value)return '';
 let url;try{url=new URL(value);}catch{throw Error('Paste the full HTTPS link to your Google Business listing or Google Maps pin.');}
 if(url.protocol!=='https:'||url.username||url.password||url.port)throw Error('Use a secure Google Business or Google Maps link.');
 const host=url.hostname.toLowerCase(),path=url.pathname;
 const allowed=(['google.com','www.google.com','google.co.in','www.google.co.in'].includes(host)&&/^\/maps(?:\/|$)/.test(path))||['maps.google.com','maps.google.co.in','maps.app.goo.gl','g.page'].includes(host)||(host==='g.co'&&path.startsWith('/kgs/'));
 if(!allowed)throw Error('Use a Google Maps sharing link or a public Google Business listing link.');
 return url.href;
}
function isSavedStudioLocation(value){const flat=text=>String(text||'').replace(/\s+/g,' ').trim();return flat(value)===flat(S.profile.studioAddress||S.profile.area);}
function studioLocationFields(){return `<section class="studio-location-fields"><hr class="rule"><div class="section-head"><div><span class="eyebrow">Help clients find you</span><h2>Google Business & studio location</h2></div>${S.profile.googleMapsUrl?tag('Link added','green'):tag('Optional')}</div><p class="small">Add your public Google listing and the studio address clients should visit.</p><div style="margin-top:20px">${formField('Google Business / Maps link','googleMapsUrl',S.profile.googleMapsUrl||'','url','On Google Maps, open your studio listing, choose Share and copy the link.')}${textField('Full studio address','studioAddress',S.profile.studioAddress||'','Include the building, floor, street and postcode. This address appears on your public profile.')}${formField('Landmark / arrival instructions','studioLandmark',S.profile.studioLandmark||'','text','Optional: entrance, parking or a nearby landmark.')}</div><p class="help">Adding a link does not claim or verify your Google Business profile.</p></section>`;}
function studioLocationPanel(x){
 const own=x.id===0,address=own?String(S.profile.studioAddress||'').trim():'',landmark=own?String(S.profile.studioLandmark||'').trim():'';
 let url='';try{url=own?googleBusinessLink(S.profile.googleMapsUrl):'';}catch{}
 if(!address&&!url)return row('Studio',e(x.area)+', '+e(x.city));
 const maps=url||(address?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address+', '+x.city):'');
 return `<section class="studio-location"><h3>Studio location</h3><strong>${e(own?S.profile.studio:x.name)}</strong><p class="studio-address">${e(address||x.area+', '+x.city)}</p>${landmark?`<p class="small studio-landmark">${e(landmark)}</p>`:''}${maps?`<a href="${e(maps)}" class="btn compact" target="_blank" rel="noopener noreferrer">${url?'Open in Google Maps ↗':'Search address on Google Maps ↗'}</a>`:''}${!address?'<p class="help">See the Google listing for the precise address.</p>':''}</section>`;
}
function studioQuoteLink(b){
 if(b.service==='home'||!b.quote)return '';
 let url='';try{url=googleBusinessLink(b.quote.googleMapsUrl);}catch{}
 const exact=!!url;if(!url&&b.quote.location)url='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.quote.location);
 if(!url)return '';
 return `<div class="studio-quote-link"><a href="${e(url)}" class="btn compact" target="_blank" rel="noopener noreferrer">${exact?'Open studio in Google Maps ↗':'Search address on Google Maps ↗'}</a>${b.quote.studioLandmark?`<p class="help">${e(b.quote.studioLandmark)}</p>`:''}</div>`;
}

function artistSettings(){return `${setupBack()}${head('Public profile','Profile & settings','Make it easy for clients to understand your work.')}<form class="card" data-form="artist-settings"><div class="grid two">${formField('Artist name','name',S.profile.name,'text','',true)}${formField('Studio / business','studio',S.profile.studio)}${formField('City','city',S.profile.city,'text','',true)}${formField('Studio area','area',S.profile.area,'text','',true)}${formField('Starting tattoo price (₹)','starting',S.profile.starting,'number','Indicative starting price. Quote each tattoo individually.',true)}</div>${studioLocationFields()}${textField('About your work','about',S.profile.about)}<div class="field"><div class="label">Specialities</div><div class="inline-field">${['Fine line','Black & grey','Realism','Colour','Illustrative'].map(t=>`<label><input type="checkbox" name="styles" value="${e(t)}" ${S.profile.styles.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><hr class="rule"><label class="inline-field"><input type="checkbox" name="active" ${S.profile.active?'checked':''}><span>Accepting new enquiries</span></label><p class="help">Pausing hides your profile from new discovery. Your current bookings remain accessible.</p><div class="error" data-error role="alert" hidden></div><button type="submit" class="btn primary" style="margin-top:23px">${inProfileSetup()?'Save & return to profile setup':'Save profile'}</button></form>`;}
function adminDashboard(){return `${head('Operations','Keep the marketplace running.','Artist approval, booking oversight and support.')}<div class="stats"><div class="card stat"><p>Profile reviews</p><div class="number">${S.profile.submitted&&!S.profile.approved?1:0}</div></div><div class="card stat"><p>Platform bookings</p><div class="number">${S.bookings.length}</div></div><div class="card stat"><p>Open support issues</p><div class="number">${S.tickets.filter(t=>!t.closed).length}</div></div></div><div class="grid two"><div class="card"><h2>Artist approval</h2><p style="margin:13px 0 20px">Review profiles before they appear publicly. Record what was checked.</p>${a('admin-artists','Review artists →','btn')}</div><div class="card"><h2>Booking oversight</h2><p style="margin:13px 0 20px">See the quote, client acceptance, advance payment and commission event for each booking.</p>${a('admin-bookings','View bookings →','btn')}</div></div><div class="note" style="margin-top:22px">The Admin switch is a prototype review tool. The live product requires separate, permission-protected admin access and an audit log.</div>`;}
function adminArtists(){return `${head('Profile quality','Artist review','Approval is a documented review step, not a blanket quality or safety guarantee.')}<div class="split"><div class="stack"><div class="card"><h2>${e(S.profile.name)}</h2><p style="margin-top:12px">${e(S.profile.about)}</p><hr class="rule">${row('Studio area',e(S.profile.area))}${row('Starting price',money(S.profile.starting))}${row('Specialities',e(S.profile.styles.join(', ')))}${row('Home service',S.home.enabled?'Available':'Off')}${row('Review status',S.profile.approved?'Approved':S.profile.submitted?'Pending review':'Draft')}<div class="portfolio">${S.gallery.map(im=>`<img src="${e(im)}" alt="Submitted sample portfolio">`).join('')}</div></div></div><form class="card" data-form="approval"><h2>Review checklist</h2><div class="stack" style="margin:20px 0"><label class="inline-field"><input type="checkbox" name="identity" required>Identity & contact details checked</label><label class="inline-field"><input type="checkbox" name="portfolio" required>Portfolio ownership checked</label><label class="inline-field"><input type="checkbox" name="services" required>Prices & services checked</label></div><div class="note">Demo checkboxes illustrate the workflow; they do not perform verification.</div><button class="btn primary full" type="submit" style="margin-top:20px">Approve demo profile</button><div style="margin-top:12px">${btn('reject-profile','Request profile changes','btn full')}</div></form></div>`;}
function adminBookings(){return `${head('Booking oversight','Platform bookings','Follow the client-approved quote and session record.')}<div class="card table-wrap"><table class="table"><thead><tr><th>Booking</th><th>Service</th><th>Status</th><th>Tattoo / travel</th><th>Commission</th><th>Open</th></tr></thead><tbody>${S.bookings.map(b=>`<tr><td><strong>${e(b.id)}</strong><br>${e(b.client)}</td><td>${b.service==='home'?'Home visit':'Studio'}</td><td>${tag(names[b.status])}</td><td>${b.quote?money(b.quote.amount)+' / '+money(b.quote.travel):'Not quoted'}</td><td>${b.charged?money(b.commission):'Not charged'}</td><td>${a('artist-booking','Details','btn compact')}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:20px">Before-start cancellations have no commission in this design. Disputes after a session starts require manual review rather than an automatic wallet refund.</div>`;}
function adminSupport(){return `${head('Support','Resolve booking issues.','Each report stays linked to its booking.')}<div class="stack">${S.tickets.length?S.tickets.map(t=>`<div class="card"><div class="section-head"><h2>${e(t.issue)}</h2>${tag(t.closed?'Closed':'Open',t.closed?'green':'brand')}</div><p class="small">${e(t.id)} · ${e(t.booking)}</p><p style="margin-top:16px">${e(t.details)}</p><div style="margin-top:20px">${t.closed?'<p class="help">Demo issue marked resolved. No real messages or refunds were sent.</p>':btn('close-ticket','Mark resolved','btn primary',`data-id="${t.id}"`)}</div></div>`).join(''):`<div class="card empty"><h2>No support issues yet.</h2><p>Create a demo report from Help to inspect the support workflow.</p>${a('help','Open help','btn primary')}</div>`}</div>`;}
function flowSteps(items){return items.map(([title,description,url])=>`<div class="flow-step"><h3>${e(title)}</h3><p>${description}</p>${url?a(url,'Open screen →','small'):''}</div>`).join('');}
function workflowPage(){return `<main class="content">${head('Product blueprint','Simple to use. Clear underneath.','Client, artist and admin workflows, plus the rules that connect them.',a('screens','Browse all '+screens.length+' screens','btn primary'))}<div class="workflow-lanes"><section class="card flow-lane"><h2>Client journey</h2>${flowSteps([['Discover','Sign in with the Google or phone/OTP preview, or browse artists first.','home'],['Compare','View portfolios; search an artist by name and filter by style and a price slider up to ₹1,00,000.','artists'],['Share an idea','Three short steps: idea → clickable body placement, familiar size & budget → appointment & timing. Locality is required only for home visits. Drafts stay when going back.','enquiry'],['Consult','Sign in when sending. Discuss the idea with the artist.','conversation'],['Pay & approve','Review the quote. If the artist requires an advance, agree to the terms and pay to confirm in one flow. For home service, add your address.','quote'],['Attend','Show a booking-specific code at the session start.','appointment'],['Review','A review prompt opens for the client after completion; the review is linked to the booking.','review']])}</section><section class="card flow-lane"><h2>Artist journey</h2>${flowSteps([['Join','Create profile, add portfolio and set prices and services.','artist-welcome'],['Get approved','Submit profile for review. Draft/pending profiles stay out of search.','artist-onboarding'],['Receive an enquiry','Review placement, budget, references and locality. Reply or decline.','artist-enquiries'],['Quote','Confirm the tattoo amount, travel charge, date and location. An optional advance is paid before the client accepts and confirms.','artist-quote'],['Start the session','Enter client OTP. Record the fixed artist booking fee once from the artist wallet.','artist-start'],['Complete','Mark the appointment completed, then choose an aftercare template to send to that client.','artist-complete'],['Manage visibility','Negative wallet hides discovery; clearing dues restores it if the profile is approved and active.','artist-wallet']])}</section><section class="card flow-lane"><h2>Admin journey</h2>${flowSteps([['Review profiles','Identity, contact information, portfolio ownership and services need explicit review definitions.','admin-artists'],['Oversee bookings','Keep quoted, accepted, started and completed states distinct.','admin-bookings'],['Handle issues','Support can review price disputes, no-shows and after-start cancellations.','admin-support'],['Maintain an audit trail','Production actions record who changed what and when. Wallet deductions must be server-enforced.',null]])}</section></div><div class="grid two" style="margin-top:28px"><div class="card"><h2>Booking states</h2><div class="status-path">${['Enquiry','Quote','Booked','In session','Completed','Reviewed'].map(t=>tag(t)).join('')}</div><p class="small">Enquiry, quote and booked appointments can be cancelled before session start. After start, issues go to support. Sending a revised quote invalidates the earlier offer; accepted prices cannot be silently edited. Quotes with a paid advance are locked.</p></div><div class="card"><h2>Home-service branch</h2><p style="margin-top:15px">Home-service filter → artist covers locality → travel charge agreed → address provided at confirmation → appointment details checked → session code → completion.</p><p class="small" style="margin-top:15px">Turning home service off affects future discovery. It does not delete previously agreed appointments.</p></div></div><div class="card" style="margin-top:28px"><h2>Commission & wallet rules</h2>${row('Commission event','Successful start-session OTP')}${row('Artist fee details','Shown after profile creation, inside the artist workspace')}${row('Duplicate code submission','No second deduction')}${row('Wallet below zero','Hide public profile; retain existing bookings')}${row('Wallet zero or above','Restore discovery if approved and active')}${row('Before-start cancellation','No commission deducted')}<div class="design-note">Your ranking idea is retained as a planned product rule: booking value and verified booking history can influence exposure and budget matching. The demo uses name, style, city and price filters; it does not claim that a higher-priced artist is better. The ranking formula and artist incentive to record every booking still need validation.</div></div><div class="card" style="margin-top:28px"><h2>Navigation & interaction rules</h2><div class="grid two" style="margin-top:20px"><div><h3>Client navigation</h3><p style="margin-top:10px">Explore · Saved · My requests · Account<br>Artist joining stays a secondary link.</p></div><div><h3>Artist navigation</h3><p style="margin-top:10px">Overview · Enquiries · Bookings · Portfolio · Home service · Wallet · Settings</p></div></div><hr class="rule"><p>One main action per screen. Keep the opening page free of artist cards. Keep forms short. Show a clear empty state. Preserve drafts. Show starting prices as estimates. Avoid login until enquiry submission. Keep commission and admin controls out of the client journey.</p></div><div class="card" style="margin-top:28px"><h2>What this prototype does</h2><p style="margin-top:15px">Clickable client, artist and admin screens; browser-local messages, image attachments and drafts; quotes, acceptance, cancellation, session start, completion, reviews and wallet simulation; home-service settings; saved artists; profile review; support requests; responsive layouts.</p><hr class="rule"><h3>What the production build still needs</h3><p style="margin-top:12px">Real authentication and role permissions, database and uploads, unique expiring SMS codes, notifications, advance-payment and wallet top-up integration, payment success webhooks, artist payouts/refunds, server-side transaction and commission enforcement, ranking logic, location coverage, moderation, audit logs, privacy and cancellation policies. Admin and role switches here are for preview only.</p></div><div class="card" style="margin-top:28px"><h2>Try the complete journey</h2><ol><li>Client: choose an artist and send an enquiry.</li><li>Artist: open the enquiry and send a quote.</li><li>Client: review the quote and pay any required advance to confirm. With no advance, confirm directly.</li><li>Artist: start the session with demo code <strong>123456</strong>.</li><li>Open Wallet: see the single commission event and visibility change.</li><li>Artist: complete the session. Client: leave a review.</li><li>Add demo wallet funds to restore discovery.</li></ol><p class="small">The seeded enquiry has a suggested ₹14,000 tattoo quote. Switch to the artist workspace to inspect the booking fee and wallet activity.</p></div></main>`;}
function screenPage(){return `<main class="content">${head('Complete page map','Every screen, one place.',`${screens.length} screens across client, artist, admin and workflow review.`)}${['Client','Artist','Admin','Design'].map(group=>`<section style="margin-bottom:35px"><div class="section-head"><h2>${group}</h2><span class="small">${screens.filter(x=>x[1]===group).length} screens</span></div><div class="screen-index">${screens.filter(x=>x[1]===group).map(([url,g,title,desc])=>a(url,`<strong>${e(title)}</strong><small>${e(desc)}</small>`,'screen-link')).join('')}</div></section>`).join('')}</main>`;}
function missing(){return `<div class="card empty"><h2>No booking selected.</h2><p>Open an enquiry or start a new tattoo request.</p>${a('requests','My requests','btn primary')}</div>`;}
screens.push(['booking','Client','Your tattoo','One page for your booking'],['artist','Client','Book your artist','Artist’s own booking page'],['artist-links','Artist','Booking links','Personal page and quote links'],['artist-new-booking','Artist','Create client booking','Create an agreed quote'],['artist-calendar','Artist','Calendar','Appointments and preparation time'],['artist-payments','Artist','Payments','Advance and balance records'],['artist-templates','Artist','Templates & replies','Reusable starting points'],['artist-reschedule','Artist','Reschedule','Client-approved changes'],['admin-metrics','Admin','Pilot insights','Booking activity']);
const pages={booking:bookingHubPage,artist:artistLinkPage,'artist-links':artistLinksPage,'artist-new-booking':artistNewBookingPage,'artist-calendar':artistCalendarPage,'artist-payments':artistPaymentsPage,'artist-templates':artistTemplatesPage,'artist-reschedule':reschedulePage,'admin-metrics':pilotMetricsPage,home:homePage,artists:artistsPage,profile:profilePage,enquiry:enquiryPage,login:loginPage,requests:requestsPage,conversation:()=>`<main class="content">${a('requests','← My requests','back')}${conversationPage()}</main>`,quote:quotePage,advance:advancePage,appointment:()=>`<main class="content">${a('appointments','← Appointments','back')}${appointmentPage()}</main>`,appointments:appointmentsPage,review:reviewPage,saved:savedPage,account:accountPage,help:helpPage,'artist-welcome':artistWelcome,'artist-signup':artistSignup,'artist-onboarding':artistOnboarding,'artist-dashboard':artistDashboard,'artist-enquiries':artistEnquiries,'artist-enquiry':()=>conversationPage(true),'artist-quote':artistQuote,'artist-bookings':artistBookings,'artist-booking':()=>appointmentPage(true),'artist-start':artistStart,'artist-complete':artistComplete,'artist-wallet':walletPage,'artist-portfolio':portfolioPage,'artist-home':homeSettings,'artist-settings':artistSettings,'admin-dashboard':adminDashboard,'admin-artists':adminArtists,'admin-bookings':adminBookings,'admin-support':adminSupport,workflow:workflowPage,screens:screenPage};
for(const legacy of ['conversation','quote','advance','appointment','review'])pages[legacy]=bookingHubPage;
function render(){const bookingIdFromRoute=bookingFromRoute();if(bookingIdFromRoute&&bookingIdFromRoute!==S.selectedBooking){S.selectedBooking=bookingIdFromRoute;save();}let r=route();if(!pages[r])r='home';const shell=(r.startsWith('artist-')&&!['artist-welcome','artist-signup'].includes(r))||r.startsWith('admin-');B.ensure(S);const artistParam=new URLSearchParams(location.hash.split('?')[1]||'').get('artist');if(artistParam!==null&&artists().some(x=>String(x.id)===artistParam))S.selectedArtist=Number(artistParam);const content=pages[r]();document.getElementById('app').innerHTML=topbar(r)+header(r)+(shell?`<div class="shell">${sidebar(r,r.startsWith('admin-'))}<main class="workspace">${content}</main></div>`:content)+footer()+reviewPromptMarkup();document.title=(screens.find(x=>x[0]===r)?.[2]||'MakeMyTattoo')+' — MakeMyTattoo · by sorrymom.';document.querySelectorAll('.artist-card').forEach(card=>{const id=card.querySelector('[data-artist]')?.dataset.artist;card.querySelectorAll('a[href="#profile"]').forEach(link=>link.dataset.artist=id);});document.querySelectorAll('.list-item,.table tbody tr').forEach(el=>{const id=el.querySelector('.badge')?.textContent;const explicit=[...el.querySelectorAll('.badge')].map(x=>x.textContent).find(t=>/^T-/.test(t));const tableId=el.querySelector('td strong')?.textContent;const bookingId=explicit||tableId;if(bookingId)el.querySelectorAll('a').forEach(link=>link.dataset.booking=bookingId);});if(r==='enquiry'&&enquiryStep===3)updateLocality(S.draft.service);if(r==='artist-quote')updateAdvanceFields(!!currentBooking()?.quote?.advanceRequired);if(r==='artist-new-booking'){const check=document.querySelector('[name="advanceRequired"]');if(check)updateAdvanceFields(check.checked);}hydrateChatImages();const reviewDialog=document.querySelector('.review-overlay');if(reviewDialog){document.querySelectorAll('#app > :not(.review-overlay)').forEach(el=>el.inert=true);reviewDialog.querySelector('.close')?.focus();}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,4200);}
function formError(form,err){const el=form.querySelector('[data-error]');if(el){el.hidden=false;el.textContent=err.message||String(err);el.scrollIntoView({block:'nearest'});}else toast(err.message||String(err));}
function updateDraft(form){const fd=new FormData(form);for(const k of ['idea','placement','size','budget','service','area','datePreference'])if(fd.has(k))S.draft[k]=fd.get(k);save();}
function validateEnquiryLocation(d,x){if(d.service==='home'){if(!x.home)throw Error('This artist does not offer home service. Choose a studio appointment.');if(!String(d.area||'').trim())throw Error('Enter your locality for a home visit.');}}
function sendEnquiry(){
 const x=selectedArtist(),d=S.draft;validateEnquiryLocation(d,x);
 const id='T-'+(1001+S.bookings.length);
 const b={id,artist:x.id,client:S.client.name,idea:d.idea,placement:d.placement||'Not sure yet',size:d.size||'Not sure yet',budget:d.budget,service:d.service,area:d.service==='home'?d.area.trim():x.area,address:'',datePreference:d.datePreference,status:'requested',createdAt:Date.now(),shareToken:B.id('link'),source:'marketplace',quote:null,charged:false,messages:[{from:'client',text:d.idea}],reference:d.reference,referenceImage:''};
 S.bookings.unshift(b);S.selectedBooking=id;S.draft=seed().draft;enquiryStep=1;save();go('booking?booking='+encodeURIComponent(id));toast('Demo enquiry sent. Switch to Artist to reply.');
}
function modal(title,text,action,label='Confirm'){document.querySelector('.modal-overlay')?.remove();const wrap=document.createElement('div');wrap.className='modal-overlay';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><button class="close" aria-label="Close dialog" data-action="close-modal">×</button><h2>${title}</h2><p>${text}</p><div class="actions">${btn(action,label,'btn primary')}${btn('close-modal','Keep current state')}</div></section>`;document.body.append(wrap);wrap.querySelector('.close').focus();wrap.addEventListener('keydown',ev=>{if(ev.key==='Escape')wrap.remove();if(ev.key==='Tab'){const focusable=[...wrap.querySelectorAll('button,a,input')];let first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});}
document.addEventListener('click',ev=>{const link=ev.target.closest('a');if(link){if(link.dataset.artist!==undefined){S.selectedArtist=Number(link.dataset.artist);save();if(route()==='profile')setTimeout(render,0);}if(link.dataset.booking){S.selectedBooking=link.dataset.booking;save();if(link.hash==='#'+route())setTimeout(render,0);}}const button=ev.target.closest('[data-action]');if(!button)return;if(button.dataset.booking){S.selectedBooking=button.dataset.booking;save();}const act=button.dataset.action,b=currentBooking();if(typeof CloudStore!=='undefined'&&CloudStore.loading){toast('Your saved workspace is loading. Please try again in a moment.');return;}try{
  if(experienceClick(act,button,b))return;
  if(act==='google-preview'){modal('Google sign-in preview','Live Google sign-in is not connected in this prototype. Continue with the demo client to try the booking flow.','google-demo-login','Continue as demo client');}
  if(act==='google-demo-login'){document.querySelector('.modal-overlay')?.remove();finishDemoSignIn('google-demo');}
  if(act==='change-login-number'){authPreview.step='phone';render();}
  if(act==='resend-demo-code'){authPreview.expires=Date.now()+300000;authPreview.attempts=0;render();toast('Demo code: 123456. No SMS was sent.');}
  if(act==='review-later')dismissReview(button.dataset.reviewBooking);
  if(act==='disconnect-instagram'){S.profile.instagram={handle:'',posts:[]};save();render();toast('Instagram portfolio link removed.');}
  if(act==='pick-chat-images')document.getElementById('chat-images')?.click();
  if(act==='remove-chat-image'){const d=chatDraft(button.dataset.booking,button.dataset.sender),[image]=d.images.splice(Number(button.dataset.index),1);if(image)URL.revokeObjectURL(image.url);render();}
  if(act==='view-chat-image')showChatImage(button.dataset.media,button.dataset.name);
  if(act==='service'){S.search.service=button.dataset.value;save();document.querySelectorAll('[data-action="service"]').forEach(p=>p.setAttribute('aria-pressed',String(p===button)));}
  if(act==='body-view'){updateDraft(document.querySelector('[data-form="enquiry"]'));bodyView=button.dataset.value;render();document.querySelector('[data-action="body-view"][data-value="'+bodyView+'"]')?.focus();}
  if(act==='placement')choosePlacement(button.dataset.value);
  if(act==='size')chooseSize(button.dataset.value);
  if(act==='clear-filters'){S.search={city:S.search.city,service:'either',style:'All styles',maxPrice:100000,name:''};save();render();}
  if(act==='save-artist'){const id=Number(button.dataset.id);S.saved=S.saved.includes(id)?S.saved.filter(x=>x!==id):[...S.saved,id];save();render();}
  if(act==='new-enquiry'){S.selectedArtist=Number(button.dataset.id);const x=selectedArtist();S.draft.service=S.search.service==='home'&&x.home?'home':'studio';enquiryStep=1;save();go('enquiry');}
  if(act==='enquiry-back'){updateDraft(document.querySelector('[data-form="enquiry"]'));enquiryStep=Math.max(1,enquiryStep-1);render();}
  if(act==='rating'){rating=Number(button.dataset.value);document.querySelectorAll('[data-action="rating"]').forEach(p=>{p.classList.toggle('chosen',Number(p.dataset.value)<=rating);p.setAttribute('aria-pressed',String(Number(p.dataset.value)===rating));});}
  if(act==='logout'){S.client.signedIn=false;authPreview={step:'phone',phone:'',expires:0,attempts:0};save();go('home');render();toast('Signed out of demo.');}
  if(act==='cancel-booking'){modal('Cancel this appointment?',b.advance?.status==='paid'?'This cancels the appointment. Your paid advance stays recorded; any refund is handled by the artist under the agreed terms.':'This will close the enquiry or appointment. You can start a new request whenever you’re ready.','confirm-cancel','Cancel appointment');}
  if(act==='confirm-cancel'){M.cancelBooking(b,'Cancelled from demo');save();document.querySelector('.modal-overlay')?.remove();render();toast('Appointment cancelled.');}
  if(act==='close-modal')document.querySelector('.modal-overlay')?.remove();
  if(act==='reset'){modal('Reset the design preview?','This clears only this browser’s demo enquiries, messages, reviews, profile changes and wallet transactions.','confirm-reset','Reset demo');}
  if(act==='confirm-reset'){chatDrafts.forEach(d=>d.images.forEach(im=>URL.revokeObjectURL(im.url)));chatDrafts.clear();reviewDrafts.clear();ChatMedia.clear().catch(()=>{});S=seed();B.ensure(S);authPreview={step:'phone',phone:'',expires:0,attempts:0};bodyView='front';enquiryStep=1;rating=0;localGallery.forEach(URL.revokeObjectURL);localGallery=[];if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL='';save();document.querySelector('.modal-overlay')?.remove();go('home');render();toast('Demo reset.');}
  if(act==='advance-payment-fail'){B.pay(S,b,'failed');save();render();toast('Demo payment failed. No wallet credit was made.');}
  if(act==='refund-advance'){modal('Refund this advance?','This returns the full '+money(b.advance.amount)+' advance in the demo and deducts it from the artist wallet. No actual money is transferred.','confirm-refund-advance','Refund advance (demo)');}
  if(act==='confirm-refund-advance'){M.refundAdvance(b,S.wallet);save();document.querySelector('.modal-overlay')?.remove();render();toast('Demo advance refunded once.');}
  if(act==='finish-portfolio-setup'){S.setup.portfolio=true;save();go('artist-onboarding');toast('Portfolio saved.');}
  if(act==='submit-profile'){if(!S.gallery.length)throw Error('Add at least one portfolio example first.');if(!S.profile.styles.length)throw Error('Choose at least one speciality first.');S.profile.submitted=true;S.profile.approved=false;save();render();toast('Demo profile submitted. Open Admin to review.');}
  if(act==='reject-profile'){S.profile.approved=false;S.profile.submitted=false;save();render();toast('Profile returned to draft for changes.');}
  if(act==='close-ticket'){const t=S.tickets.find(t=>t.id===button.dataset.id);if(t)t.closed=true;save();render();toast('Demo support issue marked resolved.');}
  if(act==='portfolio-remove'){if(S.gallery.length<=1)throw Error('Keep at least one portfolio image.');S.gallery.splice(Number(button.dataset.index),1);save();render();}
  if(act==='portfolio-up'){const i=Number(button.dataset.index),[im]=S.gallery.splice(i,1);S.gallery.unshift(im);save();render();}
  if(act==='add-sample'){S.gallery.push(artFiles[S.gallery.length%artFiles.length]);save();render();toast('Sample artwork added.');}
}catch(err){toast(err.message);}});
document.addEventListener('submit',ev=>{const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();if(typeof CloudStore!=='undefined'&&CloudStore.loading){toast('Your saved workspace is loading. Please try again in a moment.');return;}const fd=new FormData(form),f=form.dataset.form,b=form.dataset.booking?S.bookings.find(item=>item.id===form.dataset.booking):currentBooking();try{
 if(experienceSubmit(f,form,fd,b))return;
 if(f==='phone-login'){const phone=String(fd.get('phone')||'').trim();if(!/^\+?[0-9 ()-]{7,22}$/.test(phone)||!/^\d{7,15}$/.test(phone.replace(/\D/g,'')))throw Error('Enter a valid demo mobile number, including country code.');authPreview={step:'otp',phone,expires:Date.now()+300000,attempts:0};render();toast('Preview code: 123456. No SMS was sent.');}
 if(f==='verify-login'){if(authPreview.step!=='otp'||Date.now()>authPreview.expires)throw Error('This demo code expired. Request a new one.');if(authPreview.attempts>=5)throw Error('Too many attempts. Request a new demo code.');authPreview.attempts++;if(String(fd.get('code')||'').trim()!=='123456')throw Error('Incorrect demo code. Use 123456.');finishDemoSignIn('phone');}
 if(f==='instagram-portfolio'){const handle=instagramHandle(fd.get('instagram')),posts=instagramPosts(fd.get('instagramPosts'));if(posts.length&&!handle)throw Error('Add your Instagram profile before recent work links.');S.profile.instagram={handle,posts};save();render();toast(handle?'Instagram portfolio linked.':'Instagram portfolio removed.');}
 if(f==='search'){S.search.city=String(fd.get('city')).trim();S.search.style='All styles';S.search.maxPrice=100000;S.search.name='';save();go('artists');}
 if(f==='filters'){S.search={city:String(fd.get('city')).trim(),name:String(fd.get('artistName')||'').trim(),style:fd.get('style'),maxPrice:priceLimit(fd.get('maxPrice')??100000),service:fd.get('service')==='At my place'?'home':fd.get('service')==='At a studio'?'studio':'either'};save();render();}
 if(f==='enquiry'){updateDraft(form);if(enquiryStep<3){enquiryStep++;render();window.scrollTo({top:0});}else{validateEnquiryLocation(S.draft,selectedArtist());if(!S.client.signedIn){S.draft.awaitingSignIn=true;save();go('login');}else sendEnquiry();}}

 if(f==='account'){S.client.name=String(fd.get('name')).trim();S.client.email=String(fd.get('email')).trim();S.client.signedIn=true;save();render();toast('Demo account details saved.');}
 if(f==='message'){sendChatMessage(form,b,fd).catch(err=>formError(form,err));return;}
 if(f==='artist-signup'){S.profile.name=String(fd.get('name')).trim();S.profile.studio=String(fd.get('studio')).trim();S.profile.city=String(fd.get('city')).trim();S.profile.approved=false;S.profile.submitted=false;S.setup={details:false,portfolio:false,appointments:false};save();go('artist-onboarding');}
 if(f==='artist-quote'){const amount=Number(fd.get('amount')),travel=b.service==='home'?Number(fd.get('travel')):0,advanceRequired=fd.has('advanceRequired');const scheduleValues={duration:b.quote?.duration??S.profile.schedule?.defaultDuration??180,prep:b.quote?.prep??S.profile.schedule?.prep??30};B.assertAvailable(S,b,{...scheduleValues,date:fd.get('date'),time:fd.get('time')});M.publishQuote(b,{...scheduleValues,amount,travel,advanceRequired,advanceAmount:advanceRequired?Number(fd.get('advanceAmount')):0,advancePolicy:advanceRequired?String(fd.get('advancePolicy')||''):'',date:fd.get('date'),time:fd.get('time'),location:String(fd.get('location')).trim(),googleMapsUrl:b.service==='studio'&&b.artist===0&&isSavedStudioLocation(fd.get('location'))?googleBusinessLink(S.profile.googleMapsUrl):'',studioLandmark:b.service==='studio'&&b.artist===0&&isSavedStudioLocation(fd.get('location'))?String(S.profile.studioLandmark||'').trim():'',notes:String(fd.get('notes')).trim()});b.firstArtistReplyAt=b.firstArtistReplyAt||Date.now();b.messages.push({from:'artist',at:Date.now(),text:'I’ve sent your appointment quote. Please check the amount, date and location before accepting.'});save();go('artist-enquiry');toast('Quote sent. Switch to Client to review it.');}
 if(f==='accept-quote'){if(!S.client.signedIn){if(b.service==='home')b.address=String(fd.get('address')||'').trim();S.authReturn='booking?booking='+encodeURIComponent(b.id);save();go('login');return;}if(!fd.has('agreed'))throw Error('Agree to the quote before confirming.');if(b.service==='home')b.address=String(fd.get('address')).trim();if(b.service==='home'&&!b.address)throw Error('Add your home-service address.');if(M.requiredAdvance(b.quote)>0&&!M.advancePaid(b)){B.prepare(S,b);save();go('booking?booking='+encodeURIComponent(b.id)+'&pay=1');}else{B.confirm(S,b);save();go('booking?booking='+encodeURIComponent(b.id));toast('Appointment confirmed.');}}
 if(f==='pay-advance'){B.pay(S,b);save();go('booking?booking='+encodeURIComponent(b.id));toast('Appointment confirmed. Advance recorded in the demo.');}
 if(f==='start'){if(!fd.has('agreed'))throw Error('Confirm the appointment details with the client.');const fee=M.startSession(b,S.wallet,String(fd.get('otp')).trim());S.selectedBooking=b.id;save();go('artist-booking?booking='+encodeURIComponent(b.id));toast('Session started. '+money(fee)+' commission recorded once.');}
 if(f==='complete'){if(!fd.has('done'))throw Error('Confirm completion.');M.completeSession(b);b.completedAt=Date.now();b.reviewPromptDismissed=false;B.notify(S,b,'completed','Your artist marked the session completed. Share your experience.');b.aftercare=String(fd.get('aftercare')||'').trim();S.selectedBooking=b.id;save();go('artist-booking?booking='+encodeURIComponent(b.id));toast('Session completed. Choose an aftercare message for '+b.client+'.');}
 if(f==='review'){M.reviewBooking(b,rating,String(fd.get('review')).trim());b.reviewPromptDismissed=true;reviewDrafts.delete(b.id);S.selectedArtist=b.artist;rating=0;save();render();toast('Thank you. Your demo review is saved.');}
 if(f==='topup'){M.addFunds(S.wallet,Number(fd.get('amount')));save();render();toast('Demo funds added. No payment was processed.');}
 if(f==='home-settings'){const radius=Number(fd.get('radius')),travel=Number(fd.get('travel'));if(!Number.isFinite(radius)||radius<=0||!Number.isFinite(travel)||travel<0)throw Error('Use a positive travel distance and a travel charge of zero or more.');S.home={enabled:fd.has('enabled'),areas:String(fd.get('areas')).trim(),radius,travel,note:String(fd.get('note')).trim()};S.setup.appointments=true;save();if(inProfileSetup())go('artist-onboarding');else render();toast('Appointment options saved.');}
 if(f==='artist-settings'){const starting=Number(fd.get('starting'));if(!Number.isFinite(starting)||starting<=0)throw Error('Enter a starting price greater than zero.');const styles=fd.getAll('styles');if(!styles.length)throw Error('Choose at least one speciality.');const studioInfo=fd.has('googleMapsUrl')?{googleMapsUrl:googleBusinessLink(fd.get('googleMapsUrl')),studioAddress:String(fd.get('studioAddress')||'').trim(),studioLandmark:String(fd.get('studioLandmark')||'').trim()}:{};Object.assign(S.profile,{...studioInfo,name:String(fd.get('name')).trim(),studio:String(fd.get('studio')).trim(),city:String(fd.get('city')).trim(),area:String(fd.get('area')).trim(),starting,about:String(fd.get('about')).trim(),styles,active:fd.has('active')});S.setup.details=true;save();if(inProfileSetup())go('artist-onboarding');else render();toast('Artist details saved.');}
 if(f==='approval'){if(!['identity','portfolio','services'].every(k=>fd.has(k)))throw Error('Complete the review checklist.');S.profile.approved=true;S.profile.submitted=false;S.profile.checks={identity:true,portfolio:true,services:true};save();render();toast('Demo profile approved. Visibility still depends on wallet and availability.');}
 if(f==='support'){S.tickets.unshift({id:'SUP-'+(S.tickets.length+1),booking:fd.get('booking'),issue:fd.get('issue'),details:String(fd.get('details')).trim(),closed:false});save();toast('Demo report created. Open Admin → Support to review.');form.reset();}
}catch(err){formError(form,err);}});
document.addEventListener('input',ev=>{
 if(ev.target.name==='review'){const form=ev.target.closest('[data-form="review"]');if(form?.dataset.booking)reviewDrafts.set(form.dataset.booking,ev.target.value);}
 if(ev.target.name==='message'){const form=ev.target.closest('[data-form="message"]');if(form)chatDraft(form.dataset.booking,form.querySelector('[name="sender"]').value).text=ev.target.value;}
 if(ev.target.id==='starting-price'){
  const value=priceLimit(ev.target.value);const output=document.getElementById('starting-price-value');
  if(output)output.textContent=money(value);ev.target.setAttribute('aria-valuetext',money(value));
 }
 const form=ev.target.closest('[data-form="enquiry"]');if(form&&ev.target.type!=='file')updateDraft(form);
});
document.addEventListener('keydown',ev=>{const part=ev.target.closest('.body-region');if(part&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();choosePlacement(part.dataset.value);}});
document.addEventListener('wheel',ev=>{if(ev.target.id==='starting-price'&&document.activeElement===ev.target){ev.preventDefault();const n=priceLimit(Number(ev.target.value)+(ev.deltaY>0?-500:500));ev.target.value=n;document.getElementById('starting-price-value').textContent=money(n);ev.target.setAttribute('aria-valuetext',money(n));}},{passive:false});
document.addEventListener('change',ev=>{
 if(ev.target.id==='chat-images'){stageChatImages(ev.target);return;}
 if(ev.target.id==='quote-template'){applyQuoteTemplate(ev.target.value);return;}
 if(ev.target.id==='require-advance')updateAdvanceFields(ev.target.checked);
 if(ev.target.id==='f-advancePolicy')updateAdvancePolicyPreview(ev.target.value);
 if(ev.target.id==='f-service'&&ev.target.closest('[data-form="enquiry"]')){updateLocality(ev.target.value);updateDraft(ev.target.closest('[data-form="enquiry"]'));}
 if(ev.target.matches('[data-placement-select]'))choosePlacement(ev.target.value);
 if(ev.target.id==='reference-file'){const file=ev.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Select an image file.');return;}if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL=URL.createObjectURL(file);S.draft.reference=file.name;save();document.querySelector('[data-filename]').textContent=file.name;let im=document.querySelector('.upload-thumb');if(!im){im=document.createElement('img');im.className='upload-thumb';im.alt='Your selected reference';ev.target.parentElement.append(im);}im.src=referenceURL;}if(ev.target.id==='portfolio-file'){const file=ev.target.files[0];if(file&&file.type.startsWith('image/')){localGallery.push(URL.createObjectURL(file));render();}}});
window.addEventListener('storage',receiveSharedState);
window.addEventListener('focus',()=>{const value=localStorage.getItem(KEY);if(value)receiveSharedState({key:KEY,newValue:value});});
document.addEventListener('keydown',ev=>{const dialog=document.querySelector('.review-overlay');if(!dialog)return;if(ev.key==='Escape'){ev.preventDefault();dismissReview(pendingReview()?.id);}if(ev.key==='Tab'){const items=[...dialog.querySelectorAll('button,a,input,textarea')];const first=items[0],last=items.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
if(typeof CloudStore!=='undefined'){CloudStore.connectMedia(ChatMedia);CloudStore.connect({getState:()=>S,apply:applyWorkspace,status:workspaceStatus}).then(connected=>{render();if(connected)migrateLocalChatImages();});}
